window.CURRICULUM_9 = [{"id":"coordinates9","index":0,"name":"Orienting Yourself","subtitle":"The Use of Coordinates","emoji":"🧭","palette":{"from":"#38bdf8","to":"#0c4a6e"},"lessons":[{"id":"co1","title":"The Coordinate Plane","icon":"🧭","kind":"lesson","story":"When Reiaan's family moves to a new city, his sister Shalini uses pins and thread on a grid to help him feel out the layout of their new room — a hands-on introduction to one of mathematics' most powerful ideas: describing any point in space with just two numbers.","teach":[{"title":"Two perpendicular lines","body":"A coordinate plane uses two perpendicular number lines to locate any point. The horizontal line is the x-axis, the vertical line is the y-axis, and the point where they cross is the origin, O, with coordinates (0, 0).","visual":"📐"},{"title":"Reading a point's coordinates","body":"A point's coordinates (x, y) tell you its distance from each axis: x is the distance from the y-axis (measured along the x-axis), and y is the distance from the x-axis (measured along the y-axis). Distances right of O or above O are positive; left of O or below O are negative.","visual":"📍"},{"title":"The four quadrants","body":"The axes divide the plane into four quadrants. Quadrant I: both coordinates positive (+,+). Quadrant II: (−,+). Quadrant III: both negative (−,−). Quadrant IV: (+,−).","visual":"🗺️"}],"questions":[{"kind":"mcq","prompt":"The point where the x-axis and y-axis intersect is called the —","options":["Origin","Quadrant","Coordinate","Axis point"],"answer":0,"explain":"The origin O has coordinates (0, 0)."},{"kind":"numeric","prompt":"What is the x-coordinate of the origin?","answer":0,"explain":"The origin is always (0, 0)."},{"kind":"mcq","prompt":"A point with coordinates (−5, 3) lies in which quadrant?","options":["Quadrant II","Quadrant I","Quadrant III","Quadrant IV"],"answer":0,"explain":"Negative x and positive y place a point in Quadrant II."},{"kind":"mcq","prompt":"A point with coordinates (3, −5) lies in which quadrant?","options":["Quadrant IV","Quadrant I","Quadrant II","Quadrant III"],"answer":0,"explain":"Positive x and negative y place a point in Quadrant IV."},{"kind":"mcq","prompt":"Every point on the y-axis has an x-coordinate of —","options":["0","1","Undefined","Equal to its y-coordinate"],"answer":0,"explain":"Points on the y-axis have the form (0, y)."}]},{"id":"co2","title":"Plotting and Reflecting Points","icon":"📍","kind":"lesson","story":"Shalini sketches Reiaan's room to scale — doors, tables, even a bathroom — all marked with precise coordinates, so he can feel exactly where each object sits.","teach":[{"title":"Plotting from coordinates","body":"To plot P(x, y): start at the origin, move x units horizontally (right if positive, left if negative), then move y units vertically (up if positive, down if negative).","visual":"✏️"},{"title":"Reflections change signs","body":"Reflecting a point across the y-axis flips the sign of its x-coordinate: (x, y) becomes (−x, y). Reflecting across the x-axis flips the sign of the y-coordinate: (x, y) becomes (x, −y). Reflection preserves distances and shapes — only position changes.","visual":"🪞"}],"questions":[{"kind":"mcq","prompt":"Point A(3, 4) is reflected across the y-axis. What are the new coordinates?","options":["(−3, 4)","(3, −4)","(−3, −4)","(4, 3)"],"answer":0,"explain":"Reflecting across the y-axis flips the sign of the x-coordinate only."},{"kind":"mcq","prompt":"Point B(−5, 2) is reflected across the x-axis. What are the new coordinates?","options":["(−5, −2)","(5, 2)","(5, −2)","(−5, 2)"],"answer":0,"explain":"Reflecting across the x-axis flips the sign of the y-coordinate only."},{"kind":"mcq","prompt":"What happens to the side lengths of a shape when it is reflected across an axis?","options":["They stay exactly the same","They all double","They all get shorter","They become negative"],"answer":0,"explain":"Reflection is a rigid transformation — it preserves distances and shapes."},{"kind":"numeric","prompt":"A point on the x-axis has coordinates (7, y). What must y equal?","answer":0,"explain":"Every point on the x-axis has the form (x, 0)."}]},{"id":"co3","title":"The Distance Formula","icon":"📏","kind":"lesson","story":"How far apart are two points that aren't lined up neatly on an axis? By drawing a right triangle between them and calling on the Baudhāyana–Pythagoras theorem, coordinate geometry gives us an exact answer.","teach":[{"title":"Building a right triangle","body":"To find the distance between A(3, 4) and D(7, 1), draw the horizontal and vertical legs of a right triangle: the horizontal leg = difference in x-coordinates = 7 − 3 = 4; the vertical leg = difference in y-coordinates = 4 − 1 = 3.","visual":"📐"},{"title":"The distance formula","body":"Applying the Baudhāyana–Pythagoras theorem to that right triangle gives the general distance formula: distance = √((x₂−x₁)² + (y₂−y₁)²). For A(3,4) and D(7,1): √(4² + 3²) = √25 = 5 units.","visual":"√"}],"questions":[{"kind":"numeric","prompt":"Find the distance between (0, 0) and (3, 4) using the distance formula.","answer":5,"explain":"√(3² + 4²) = √(9+16) = √25 = 5."},{"kind":"numeric","prompt":"Find the distance between (1, 1) and (4, 5).","answer":5,"explain":"√((4−1)² + (5−1)²) = √(9+16) = √25 = 5."},{"kind":"mcq","prompt":"The distance formula between (x₁,y₁) and (x₂,y₂) is built directly from which theorem?","options":["The Baudhāyana–Pythagoras theorem","The angle sum property","The triangle inequality","Brahmagupta's formula"],"answer":0,"explain":"The horizontal and vertical differences form the two legs of a right triangle, and the distance is its hypotenuse."},{"kind":"mcq","prompt":"What is the distance between two points that lie on the same horizontal line, (2, 5) and (9, 5)?","options":["7","5","9","2"],"answer":0,"explain":"On a horizontal line, distance is just the absolute difference of the x-coordinates: |9−2| = 7."}]},{"id":"co-boss","title":"History of Coordinates","icon":"🏆","kind":"boss","story":"From the perfectly gridded streets of the Sindhu-Sarasvatī cities to Descartes' final leap in 17th-century Europe, the idea of coordinates took thousands of years and many civilisations to become the tool you now command.","teach":[{"title":"Ancient Indian roots","body":"The first large-scale grid systems appeared in the Sindhu-Sarasvatī Civilisation, whose city streets ran North-South and East-West at uniform ~10 metre spacing — a working coordinate system. Baudhāyana (c. 800 BCE) later used perpendicular lines for geometric constructions, laying groundwork for coordinate geometry.","visual":"🏛️"},{"title":"From Brahmagupta to Descartes","body":"Brahmagupta (c. 628 CE) formalised zero and negative numbers — essential for the origin and negative axes. Al-Bīrūnī used Indian trigonometry to calculate city coordinates. Finally, René Descartes (1637 CE) formalised that any point in a plane needs just two numbers — the coordinate system we use today is named 'Cartesian' after him.","visual":"📜"}],"boss":{"name":"The Cartographer","taunt":"Every grid, every axis, every point you've plotted — prove you can navigate them all!"},"questions":[{"kind":"mcq","prompt":"Which ancient Indian civilisation built cities with streets on a precise North-South, East-West grid?","options":["Sindhu-Sarasvatī Civilisation","Mauryan Empire","Gupta Empire","Vijayanagara Empire"],"answer":0,"explain":"Its city streets were laid out with striking precision, about 10 metres apart — a working coordinate system."},{"kind":"mcq","prompt":"Which mathematician formalised zero and negative numbers, making the four-quadrant coordinate plane possible?","options":["Brahmagupta","Āryabhaṭa","Baudhāyana","Al-Bīrūnī"],"answer":0,"explain":"Without Brahmagupta's work on zero and negatives, negative axes and quadrants II-IV couldn't exist."},{"kind":"mcq","prompt":"The coordinate system used today is called 'Cartesian' after which mathematician who formalised it in 1637?","options":["René Descartes","Isaac Newton","Pierre de Fermat","Ptolemy"],"answer":0,"explain":"Descartes showed that any point in a plane can be described by just two numbers."},{"kind":"numeric","prompt":"Find the distance between (−3, 4) and (−7, 1).","answer":5,"explain":"√((−3−(−7))² + (4−1)²) = √(16+9) = √25 = 5."},{"kind":"mcq","prompt":"A point P(x, 0) lies on which axis?","options":["The x-axis","The y-axis","Both axes","Neither axis"],"answer":0,"explain":"Points with a y-coordinate of 0 lie on the x-axis."},{"kind":"mcq","prompt":"If x ≠ y, how do the points (x, y) and (y, x) compare?","options":["They are different points","They are always the same point","They are always reflections across the origin","Neither can be plotted"],"answer":0,"explain":"Swapping unequal coordinates gives a genuinely different point, unless x = y."}]}]},{"id":"polynomials9","index":1,"name":"Introduction to Linear Polynomials","subtitle":"Ganita Manjari Chapter 2","emoji":"📈","palette":{"from":"#a78bfa","to":"#4c1d95"},"lessons":[{"id":"po1","title":"Meet the Polynomials","icon":"📦","kind":"lesson","story":"Raju walks into a shop stacked with sealed boxes of pens and pencils, and the shopkeeper challenges him to describe the total haul without opening a single box. To answer, Raju must learn the secret language of algebraic expressions -- and discover that some of them are special enough to have their own names.","teach":[{"title":"Algebraic expressions","body":"If Raju buys x red boxes (4 pens each) and y blue boxes (5 pencils each), plus gets 3 extra pens free, the total is the algebraic expression 4x + 5y + 3. Here 4x, 5y and 3 are called terms, x and y are variables (letter-numbers), 4 and 5 are coefficients of x and y, and 3 is a constant.","visual":"📦"},{"title":"One-variable polynomials","body":"An algebraic expression that involves only one variable and its powers, like x2 + 5x + 1 or 5y3 + y2 - 8, is called a one-variable or univariate polynomial. In 5y3 + y2 + 2y - 1, the coefficient of y3 is 5, of y2 is 1, of y is 2, and the constant term is -1.","visual":"🔤"},{"title":"Degree of a polynomial","body":"The highest power of the variable in a polynomial is called its degree. For example, 5y3 + y2 + 2y - 1 has degree 3, and x2 + 5x + 1 has degree 2.","visual":"📐"},{"title":"Naming polynomials by degree","body":"A degree 3 polynomial is called cubic (5y3 + y2 + 2y - 1), a degree 2 polynomial is quadratic (x2 + 5x + 1), a degree 1 polynomial is linear (3z + 7), and a degree 0 polynomial like the constant 8 (which is 8x0) is a constant polynomial.","visual":"🏷️"}],"questions":[{"kind":"mcq","prompt":"In Raju's expression 4x + 5y + 3 for pens and pencils, what is the constant term?","options":["3","4","5","x"],"answer":0,"explain":"3 is the extra free pens, a term with no variable attached, so it is the constant."},{"kind":"mcq","prompt":"What is the degree of the polynomial 5y3 + y2 + 2y - 1?","options":["3","2","1","0"],"answer":0,"explain":"The highest power of y appearing is y3, so the degree is 3."},{"kind":"mcq","prompt":"3z + 7 is an example of which type of polynomial?","options":["Linear","Quadratic","Cubic","Constant"],"answer":0,"explain":"Its degree is 1, and polynomials of degree 1 are called linear polynomials."},{"kind":"numeric","prompt":"What is the coefficient of x3 in the polynomial x4 - 3x3 + 6x2 - 2x + 7?","answer":-3,"explain":"The term with x3 is -3x3, so its coefficient is -3."},{"kind":"mcq","prompt":"The constant 8 can be written as 8x0. What type of polynomial is it?","options":["Constant","Linear","Quadratic","Cubic"],"answer":0,"explain":"Its degree is 0 (since the power of x is 0), so it is a constant polynomial."}]},{"id":"po2","title":"Linear Polynomials in Action","icon":"♟️","kind":"lesson","story":"A chess club posts its fees on the wall: a joining fee plus a charge for every match played. As players line up to pay, you notice their bills climb by the exact same amount each time -- the telltale sign of a linear polynomial at work.","teach":[{"title":"What makes a polynomial linear","body":"A polynomial of degree one is a linear polynomial. The perimeter of a square of side x is 4x, which is a linear polynomial in x.","visual":"⬜"},{"title":"The constant-difference feature","body":"A chess club charges a joining fee of Rs 200 plus Rs 50 for every match played, so the total for m matches is 200 + 50m -- a linear polynomial in m. The key feature of linear polynomials is that the amount increases by the same constant value (here, Rs 50) for every extra match.","visual":"♟️"},{"title":"From polynomial to equation","body":"When we equate a linear polynomial to a constant, we get a linear equation. For example, if the sum of two numbers is 64 and one is 10 more than the other, letting the smaller number be x gives x + (x + 10) = 64, or 2x + 10 = 64, so x = 27 and the numbers are 27 and 37.","visual":"🟰"},{"title":"Polynomials as input-output machines","body":"A polynomial can be seen as a function: for every input x, there is a corresponding output value. For the linear polynomial 2x + 3, if x = 4 the output is 2(4) + 3 = 11, and if x = -6 the output is 2(-6) + 3 = -9.","visual":"⚙️"}],"questions":[{"kind":"mcq","prompt":"The perimeter of a square of side x is 4x. What type of polynomial is this?","options":["Linear","Quadratic","Cubic","Constant"],"answer":0,"explain":"4x has degree 1, so it is a linear polynomial."},{"kind":"numeric","prompt":"A chess club charges a joining fee of Rs 200 plus Rs 50 per match, so the cost is 200 + 50m. What is the total cost for a player who played 5 matches?","answer":450,"explain":"200 + 50(5) = 200 + 250 = 450."},{"kind":"numeric","prompt":"The sum of two numbers is 64, and one number is 10 more than the other. What is the smaller number?","answer":27,"explain":"Solving 2x + 10 = 64 gives 2x = 54, so x = 27."},{"kind":"numeric","prompt":"For the linear polynomial 2x + 3, what is its value when x = -6?","answer":-9,"explain":"2(-6) + 3 = -12 + 3 = -9."},{"kind":"mcq","prompt":"Thinking of 2x + 3 as an input-output machine, what does 'evaluating the polynomial' mean?","options":["Substituting a value for the variable and computing the result","Finding the degree of the polynomial","Drawing the graph of the polynomial","Finding the y-intercept of the polynomial"],"answer":0,"explain":"Evaluating means plugging in an input value for the variable to get the corresponding output."}]},{"id":"po3","title":"Patterns, Growth and Decay","icon":"🧱","kind":"lesson","story":"Square tiles are being laid down in a growing pattern -- 1, then 3, then 5, then 7 tiles -- and the jump between stages never changes. Nearby, a water tank drains at a steady rate and an auto-rickshaw meter ticks upward km after km. All three are telling the same linear story.","teach":[{"title":"A growing tile pattern","body":"A pattern of square tiles grows as 1, 3, 5, 7, 9, 11, 13 tiles at stages 1 through 7, each stage adding two more tiles than the last. The number of squares at stage n is given by the linear polynomial 2n - 1, and the constant difference between consecutive terms is 2.","visual":"🧱"},{"title":"Linear growth","body":"Linear growth describes a pattern where a quantity increases by a constant amount over equal intervals. For a journey with cost function C(d) = 100 + 60d, the cost increases by a fixed Rs 60 for every extra km travelled.","visual":"📈"},{"title":"Linear decay","body":"Linear decay describes a pattern where a quantity decreases by a constant amount over equal intervals. The height of water in a tank, h(t) = 3 - 0.5t, decreases by a fixed 0.5 m every month.","visual":"📉"},{"title":"A fare with a flat start","body":"An auto-rickshaw fare starts at Rs 25 and stays the same for the first 2 km, then rises by Rs 15 per km after that. For a distance of n km (n greater than or equal to 2), the total fare is 25 + 15(n - 2) = 15n - 5, giving a fare of Rs 145 for a 10 km trip.","visual":"🛺"}],"questions":[{"kind":"numeric","prompt":"In the tile pattern, the number of squares at stage n is 2n - 1. How many squares are there at stage 10?","answer":19,"explain":"2(10) - 1 = 19."},{"kind":"numeric","prompt":"A journey's cost is given by C(d) = 100 + 60d. What is the cost of travelling 5 km?","answer":400,"explain":"100 + 60(5) = 100 + 300 = 400."},{"kind":"mcq","prompt":"A cylindrical tank's water height is given by h(t) = 3 - 0.5t. This is an example of:","options":["Linear decay","Linear growth","Quadratic decay","A constant function"],"answer":0,"explain":"The height decreases by a fixed 0.5 m every month, which is linear decay."},{"kind":"numeric","prompt":"An auto-rickshaw fare is Rs 25 for the first 2 km, then Rs 15 per additional km. What is the fare for a 10 km trip?","answer":145,"explain":"25 + 15 x 8 = 25 + 120 = 145."},{"kind":"mcq","prompt":"A linear pattern is a sequence of numbers where:","options":["The difference between consecutive terms is constant","The ratio between consecutive terms is constant","Each term is the square of the previous term","All the terms are equal"],"answer":0,"explain":"This constant difference is exactly what defines a linear pattern."}]},{"id":"po4","title":"Finding the Rule","icon":"📱","kind":"lesson","story":"A telecom company's bills look mysterious at first -- Rs 350 for 10 GB, Rs 550 for 20 GB -- until you realise every bill secretly follows one rule, y = ax + b. Your job is to crack the code and find the hidden fixed fee and per-GB rate.","teach":[{"title":"Linear relationships","body":"A linear relationship between two variables x and y can be expressed as y = ax + b. For the tile pattern, if x is the stage number and y is the number of square tiles, the relationship is y = 2x - 1.","visual":"🔗"},{"title":"Solving for a and b","body":"A student's phone bill was Rs 350 for 10 GB and Rs 550 for 20 GB, following y = ax + b. Substituting gives 350 = 10a + b and 550 = 20a + b; solving these together gives a = 20 and b = 150, so the relationship is y = 20x + 150.","visual":"🧮"},{"title":"What a and b represent","body":"In y = 20x + 150, the number 20 is the extra cost charged per GB of data used, and 150 is the fixed monthly fee charged regardless of usage.","visual":"💡"}],"questions":[{"kind":"numeric","prompt":"A telecom bill follows y = ax + b. If y = 350 when x = 10, and y = 550 when x = 20, what is the value of a?","answer":20,"explain":"Solving 350 = 10a + b and 550 = 20a + b together gives a = 20."},{"kind":"numeric","prompt":"Using the same relation, what is the value of b?","answer":150,"explain":"Substituting a = 20 into 350 = 10a + b gives b = 350 - 200 = 150."},{"kind":"numeric","prompt":"Using the relation y = 20x + 150, what would the bill be for a student who uses 15 GB?","answer":450,"explain":"20(15) + 150 = 300 + 150 = 450."},{"kind":"mcq","prompt":"In the bill relation y = 20x + 150, what does the 150 represent?","options":["The fixed monthly fee","The cost per GB of data","The total data used","The slope of the line"],"answer":0,"explain":"150 is the amount charged even before any data is used, i.e. the fixed fee."},{"kind":"mcq","prompt":"In the bill relation y = 20x + 150, what does the 20 represent?","options":["The additional cost per GB of data used","The fixed monthly fee","The total bill amount","The y-intercept of the line"],"answer":0,"explain":"20 multiplies x, the number of GB used, so it is the rate charged per GB."}]},{"id":"po5","title":"Graphing the Line","icon":"📊","kind":"lesson","story":"Time to bring polynomials to life on graph paper. By plotting just two points, you can draw an entire straight line -- and once you see several lines together, their slopes and y-intercepts reveal exactly how steep they are and where they cross the y-axis.","teach":[{"title":"Plotting a line from two points","body":"To plot a linear equation like y = 2x + 1, we only need two points. When x = 0, y = 1, giving point A(0, 1); when x = 3, y = 7, giving point B(3, 7). Plotting and joining A and B, then extending the line in both directions, gives the graph of y = 2x + 1.","visual":"📍"},{"title":"Slope","body":"In the equation y = ax + b, a is called the slope of the line. Lines of the form y = ax always pass through the origin (0, 0); when a > 1 the line is steeper than y = x, and when a < 1 it is less steep.","visual":"📐"},{"title":"y-intercept","body":"In y = ax + b, b is called the y-intercept, the point (0, b) where the line cuts the y-axis. For example, y = x + 3 cuts the y-axis at (0, 3), and y = 3x - 2 cuts it at (0, -2).","visual":"✂️"},{"title":"Parallel lines","body":"If we keep the slope a fixed but change b, the line shifts up or down but stays parallel to the original. So lines with equal slopes but different y-intercepts are parallel to each other.","visual":"🆟"}],"questions":[{"kind":"mcq","prompt":"In the equation y = ax + b, what does 'a' represent?","options":["The slope of the line","The y-intercept","The x-intercept","The degree of the polynomial"],"answer":0,"explain":"a tells us how steep the line is, which is the slope."},{"kind":"mcq","prompt":"What is the y-intercept of the line y = 3x - 2?","options":["-2","3","2","-3"],"answer":0,"explain":"The line cuts the y-axis at (0, -2), so the y-intercept is -2."},{"kind":"numeric","prompt":"For the line y = 2x + 1, what is the value of y when x = 3?","answer":7,"explain":"2(3) + 1 = 7, giving the point (3, 7) on the line."},{"kind":"mcq","prompt":"The lines y = 5x + 2 and y = 5x - 7 have the same slope but different y-intercepts. What can we say about them?","options":["They are parallel","They intersect at one point","They are the same line","They are perpendicular"],"answer":0,"explain":"Equal slopes with different y-intercepts always makes lines parallel."},{"kind":"mcq","prompt":"A line of the form y = ax (with no constant term) always passes through which point?","options":["The origin (0, 0)","The point (0, b)","The point (1, 1)","The point (a, b)"],"answer":0,"explain":"When b = 0, substituting x = 0 gives y = 0, so the line passes through the origin."}]},{"id":"po-boss","title":"The Polynomial Guardian","icon":"🐉","kind":"boss","story":"At the gates of the Linear Realm stands the Polynomial Guardian, testing every traveller on terms, degrees, patterns, growth, decay, and graphs before letting them pass. Only a true master of Chapter 2 can answer its riddles and move on.","boss":{"name":"The Polynomial Guardian","taunt":"Degree, slope, intercept -- name them all, or stay lost in the variables forever!"},"teach":[{"title":"Chapter recap","body":"An algebraic expression combines numbers, variables and operation symbols; a univariate polynomial has only one variable, and its degree is the highest power of that variable. A degree 1 polynomial is linear, degree 2 is quadratic, and degree 3 is cubic.","visual":"📜"},{"title":"Patterns, growth and lines","body":"A linear pattern has a constant difference between consecutive terms; linear growth increases by a fixed amount over equal intervals while linear decay decreases by a fixed amount. Every linear relationship y = ax + b is a straight line with slope a and y-intercept b, and lines with equal slopes but different y-intercepts are parallel.","visual":"🗺️"}],"questions":[{"kind":"mcq","prompt":"What is the degree of the polynomial 9x3 + 5x2 - 8x - 10?","options":["3","2","1","0"],"answer":0,"explain":"The highest power of x present is x3, so the degree is 3."},{"kind":"numeric","prompt":"Find the value of the linear polynomial 5x - 3 when x = 2.","answer":7,"explain":"5(2) - 3 = 10 - 3 = 7."},{"kind":"numeric","prompt":"A plant is 1.75 feet tall and grows 0.5 feet every month. What will its height be, in feet, after 7 months?","answer":5.25,"explain":"1.75 + 0.5 x 7 = 1.75 + 3.5 = 5.25 feet."},{"kind":"mcq","prompt":"A mobile phone bought for Rs 10,000 loses Rs 800 in value every year. This is an example of:","options":["Linear decay","Linear growth","A quadratic pattern","A constant polynomial"],"answer":0,"explain":"The value decreases by a fixed amount each year, which is linear decay."},{"kind":"mcq","prompt":"If two straight lines y = ax + b have equal slopes but different y-intercepts, the lines are:","options":["Parallel","Perpendicular","Intersecting at the origin","Identical"],"answer":0,"explain":"Equal slope with different y-intercepts is exactly the condition for parallel lines."},{"kind":"numeric","prompt":"A wire of length 20 cm is bent into a rectangle of length x cm and width (10 - x) cm, giving area x(10 - x) = 10x - x2. What is the degree of this area polynomial in x?","answer":2,"explain":"The highest power of x in 10x - x2 is x2, so the polynomial has degree 2."}]}]},{"id":"numbers9","index":2,"name":"The World of Numbers","subtitle":"Ganita Manjari Chapter 3","emoji":"🔢","palette":{"from":"#fb923c","to":"#7c2d12"},"lessons":[{"id":"wn1","title":"The Dawn of Counting","icon":"🦴","kind":"lesson","story":"Thousands of years ago on the banks of the Saraswati river, a herder needs to know if every cow that wandered into the forest has come home. There are no number-words yet, no written symbols — just a clay pot and a handful of pebbles.","teach":[{"title":"One-to-One Correspondence","body":"For every cow that left, the herder dropped one pebble into a pot; for every cow that returned, one pebble was removed. If the pot was empty at day's end, the herd was safe. This simple matching of one object to another was the birth of the Natural Numbers, N = {1, 2, 3, 4, …}.","visual":"🪨"},{"title":"A History Written in Bone","body":"The Lebombo Bone (found between South Africa and Swaziland, about 35,000 years old) has 29 carved notches, likely a lunar counter. The Ishango Bone (about 20,000 BCE, near the Nile in the Democratic Republic of Congo) groups notches into 11, 13, 17 and 19 — the prime numbers between 10 and 20 — and another column shows doubling.","visual":"🦴"},{"title":"Naming the Powers of Ten","body":"As trade grew in the Indus Valley cities of Lothal and Harappa, Indian thinkers needed ever larger numbers. The Vedas named every power of 10 up to 10¹² (called parārdha), and the Lalitavistara (4th century BCE) went as far as 10⁵³ (tallakṣhaṇa), setting the stage for the powers-of-10 system the world uses today.","visual":"📜"}],"questions":[{"kind":"mcq","prompt":"How did early herders track their cattle before written numbers existed?","options":["By matching one pebble to one cow (one-to-one correspondence)","By writing the count on tree bark","By memorising each cow's face","By using Roman numerals"],"answer":0,"explain":"A pebble was placed for every cow that left and removed for every cow that returned — the earliest form of counting."},{"kind":"numeric","prompt":"How many carved notches does the Lebombo Bone have?","answer":29,"explain":"The Lebombo Bone features 29 distinct, deliberately-carved notches, likely used as a lunar phase counter."},{"kind":"mcq","prompt":"One column of notches on the Ishango Bone groups tallies into 11, 13, 17 and 19. What do these numbers have in common?","options":["They are the prime numbers between 10 and 20","They are all even numbers","They are multiples of 3","They are perfect squares"],"answer":0,"explain":"11, 13, 17 and 19 are exactly the prime numbers between 10 and 20."},{"kind":"numeric","prompt":"According to the Vedas, names were given to every power of 10 up to which power (i.e. 10 to what exponent)?","answer":12,"explain":"The Vedas name all powers of 10 up to 10¹², called parārdha."},{"kind":"mcq","prompt":"Which set of numbers was born from the practice of one-to-one correspondence?","options":["Natural Numbers","Integers","Rational Numbers","Irrational Numbers"],"answer":0,"explain":"Matching pebbles to cows one-to-one gave rise to the Natural Numbers, N = {1, 2, 3, 4, …}."}]},{"id":"wn2","title":"The Revolution of Śhūnya","icon":"⭕","kind":"lesson","story":"If you had five apples and gave all five away, ancient number systems had no way to name what you were left with — just a void. It took Indian philosophy, and then a mathematician named Brahmagupta, to turn that void into a number.","teach":[{"title":"From Śūnyatā to Śūnya","body":"In the Upanishads and early Buddhist literature, Śūnyatā (emptiness) described the state of stillness sought through meditation. Because Indian thinkers revered this idea of emptiness, they had the philosophical groundwork to welcome 'nothingness' into mathematics, first through Āryabhaṭa and then Brahmagupta.","visual":"🧘"},{"title":"The Bakhśhālī Manuscript","body":"Dated to the early centuries CE, the Bakhśhālī Manuscript shows the physical transition from a blank space to a symbol for zero: it uses a bold dot (bindu) to represent śhūnya.","visual":"⬤"},{"title":"Brahmagupta's Rules for Zero","body":"In his Brāhmasphuṭasiddhānta (628 CE), Brahmagupta defined zero as the result of subtracting a number from itself (a – a = 0), and gave the first formal rules for it: a + 0 = a, a – 0 = a, and a × 0 = 0.","visual":"📜"}],"questions":[{"kind":"mcq","prompt":"Which ancient manuscript uses a bold dot (bindu) as a symbol for zero?","options":["The Bakhśhālī Manuscript","The Lalitavistara","The Rigveda","The Yoga Sutras"],"answer":0,"explain":"The Bakhśhālī Manuscript, dated to the early centuries CE, uses a bindu (dot) to represent zero."},{"kind":"mcq","prompt":"In which work did Brahmagupta formally lay down the rules of arithmetic with zero?","options":["Brāhmasphuṭasiddhānta (628 CE)","The Lalitavistara","The Śulbasūtra","The Yoga Sutras"],"answer":0,"explain":"Brahmagupta's Brāhmasphuṭasiddhānta (628 CE) formally defined zero and its arithmetic rules."},{"kind":"numeric","prompt":"According to Brahmagupta's rule, what is 15 − 0?","answer":15,"explain":"Brahmagupta's rule states that subtracting zero from a number leaves it unchanged: a − 0 = a."},{"kind":"numeric","prompt":"According to Brahmagupta's rule, what is 9 × 0?","answer":0,"explain":"Brahmagupta's rule states that any number multiplied by zero gives zero: a × 0 = 0."},{"kind":"mcq","prompt":"The philosophical concept of 'Śūnyatā' that inspired the mathematical zero refers to","options":["Emptiness or nothingness, sought through meditation","The cycle of the seasons","The union of opposites","A method of counting on fingers"],"answer":0,"explain":"Śūnyatā (zeroness/emptiness) was a state described in the Upanishads and Buddhist texts, later crystallising into the mathematical zero."}]},{"id":"wn3","title":"Integers: Fortunes and Debts","icon":"⚖️","kind":"lesson","story":"Brahmagupta didn't stop at zero. If 5 – 5 = 0, what happens when you subtract a bigger number from a smaller one, like 3 – 5? To answer this, he turned to the everyday reality of trade: fortunes and debts.","teach":[{"title":"Dhana and Ṝiṇa","body":"Brahmagupta recognised two states: Fortunes (Dhana), positive numbers representing wealth, and Debts (Ṝiṇa), negative numbers representing what is owed. Moving left of zero on the number line introduced Negative Numbers, and together with the natural numbers and zero, they form the Integers, denoted Z (from the German word Zahlen, meaning 'numbers').","visual":"💰"},{"title":"Brahmagupta's Arithmetic of Integers","body":"Brahmagupta gave exact rules still used today: a fortune plus a fortune is a fortune (5 + 4 = 9); a debt plus a debt is a debt ((–5) + (–4) = –9); a debt times a fortune is a debt ((–3) × 4 = –12); and the product of two debts is a fortune ((–3) × (–4) = 12).","visual":"➕"},{"title":"Why Debt Times Debt is a Fortune","body":"Think of a negative number as a debt: multiplying by a negative means removing that debt. If someone takes away four of your debts worth ₹3 each, you are ₹12 richer — so (–3) × (–4) = +12.","visual":"💡"}],"questions":[{"kind":"mcq","prompt":"In Brahmagupta's terms, what does 'Ṝiṇa' represent?","options":["A debt (negative number)","A fortune (positive number)","Zero","An irrational number"],"answer":0,"explain":"Ṝiṇa means debt, which Brahmagupta used for negative numbers, as opposed to Dhana (fortune) for positives."},{"kind":"numeric","prompt":"Using Brahmagupta's rule 'a debt plus a debt is a debt', what is (–5) + (–4)?","answer":-9,"explain":"Adding two debts gives a bigger debt: (–5) + (–4) = –9."},{"kind":"numeric","prompt":"Using Brahmagupta's rule 'the product of two debts is a fortune', what is (–3) × (–4)?","answer":12,"explain":"The product of two debts (negatives) is a fortune (positive): (–3) × (–4) = 12."},{"kind":"mcq","prompt":"The symbol Z for the set of integers comes from which word?","options":["Zahlen (German for 'numbers')","Zero (English)","Zenith (Latin)","Zircon (Persian)"],"answer":0,"explain":"Z stands for Zahlen, the German word for numbers."},{"kind":"numeric","prompt":"The temperature in Ladakh is 4°C at noon and drops by 15°C by midnight. What is the midnight temperature in °C?","answer":-11,"explain":"4 − 15 = −11, so the midnight temperature is −11°C."}]},{"id":"wn4","title":"Filling the Spaces: Rational Numbers","icon":"➗","kind":"lesson","story":"If a farmer divides a field of wheat among three children, or a recipe calls for half a cup of ghee, whole numbers and integers aren't enough. We need numbers that represent parts of a whole — fractions, and their full family, the rational numbers.","teach":[{"title":"What is a Rational Number?","body":"A rational number is any number that can be written in the form p/q, where p and q are integers and q ≠ 0. This set is denoted ℚ (for 'quotient') and includes all integers too, since any integer n can be written as n/1.","visual":"📏"},{"title":"Equivalent Fractions","body":"A rational number does not have a unique representation: −1/3 = −2/6 = −3/9 = −10/30 and so on are all equivalent fractions. We normally represent a rational number p/q on the number line in its lowest form, where p and q share no common factor other than 1 (they are co-prime).","visual":"♾️"},{"title":"Density of Rational Numbers","body":"Between any two rational numbers, you can always find another one — for example, by taking their average, which always lies between them. This means there are infinitely many rational numbers between any two points, a property called density.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"A rational number is defined as any number that can be written in the form p/q where","options":["p and q are integers and q ≠ 0","p and q are natural numbers and p > q","p and q are both irrational","p and q are prime numbers"],"answer":0,"explain":"The definition of a rational number requires p and q to be integers with q ≠ 0."},{"kind":"mcq","prompt":"What is the sum of 2/5 and 3/10?","options":["7/10","5/15","1/2","6/50"],"answer":0,"explain":"2/5 = 4/10, and 4/10 + 3/10 = 7/10."},{"kind":"mcq","prompt":"What is the absolute value |–5/3|?","options":["5/3","–5/3","0","3/5"],"answer":0,"explain":"The absolute value of a negative number is its positive value, so |–5/3| = 5/3."},{"kind":"mcq","prompt":"Which pair of rational numbers is equivalent?","options":["−1/3 and −2/6","1/2 and 2/3","3/4 and 4/5","5/6 and 7/8"],"answer":0,"explain":"Multiplying numerator and denominator of −1/3 by 2 gives −2/6, so they are equivalent."},{"kind":"mcq","prompt":"What property makes rational numbers 'dense' on the number line?","options":["Between any two rational numbers, another rational number can always be found","They can only take whole-number values","They never repeat when written as decimals","They cannot be added together"],"answer":0,"explain":"Rational numbers are dense: taking the average of any two rational numbers always produces another rational number between them."}]},{"id":"wn5","title":"Irrational Numbers: The Unfillable Gaps","icon":"📐","kind":"lesson","story":"Around 800 BCE, Baudhāyana was constructing geometric fire altars when he ran into lengths that no fraction could capture. The diagonal of a simple unit square turned out to be a number no ratio of integers could ever express.","teach":[{"title":"A Length No Fraction Can Reach","body":"For a square with sides of length 1 unit, the Baudhāyana–Pythagoras Theorem gives 1² + 1² = d², so d² = 2 and the diagonal has length √2. Numbers like this, which cannot be expressed as a ratio of integers, are called Irrational Numbers.","visual":"📐"},{"title":"Hippasus's Proof by Contradiction","body":"Hippasus (c. 400 BCE) proved √2 is irrational by assuming the opposite: that √2 = p/q in lowest terms. Squaring and rearranging shows p must be even, then substituting back shows q must also be even — but that contradicts p/q being in lowest terms, so the original assumption was false and √2 is irrational.","visual":"🧩"},{"title":"Pi and Mādhava's Infinite Series","body":"Āryabhaṭa (499 CE) gave the close approximation 3927/1250 = 3.1416 for π but called it only an asanna (approximation). π was later proven irrational by Johann Lambert in 1761. In the 14th century, Mādhava of Sangamagrama of the Kerala School discovered an exact infinite series: π = 4(1 − 1/3 + 1/5 − 1/7 + …).","visual":"🌀"}],"questions":[{"kind":"mcq","prompt":"Who gave the first proof that √2 is irrational?","options":["Hippasus","Brahmagupta","Āryabhaṭa","Mādhava of Sangamagrama"],"answer":0,"explain":"Hippasus, a member of the Pythagorean school (c. 400 BCE), gave the first proof of the irrationality of √2."},{"kind":"mcq","prompt":"What proof technique did Hippasus use to show √2 is irrational?","options":["Proof by contradiction","Proof by induction","Direct construction","Proof by exhaustion"],"answer":0,"explain":"He assumed √2 was rational and showed this assumption led to a logical contradiction."},{"kind":"mcq","prompt":"In the proof, once it is shown that p² is even, what can we conclude about p?","options":["p must be even","p must be odd","p must be zero","p must be prime"],"answer":0,"explain":"If the square of a number is even, the number itself must be even, so p is even."},{"kind":"mcq","prompt":"Who discovered the infinite series π = 4(1 − 1/3 + 1/5 − 1/7 + …)?","options":["Mādhava of Sangamagrama","Āryabhaṭa","Brahmagupta","Johann Lambert"],"answer":0,"explain":"Mādhava of Sangamagrama, founder of the Kerala School of Mathematics, discovered this infinite series for π in the 14th century."},{"kind":"mcq","prompt":"Who formally proved that π is irrational, and when?","options":["Johann Lambert, in 1761","Hippasus, in 400 BCE","Āryabhaṭa, in 499 CE","Brahmagupta, in 628 CE"],"answer":0,"explain":"The Swiss mathematician Johann Lambert proved the irrationality of π in 1761."}]},{"id":"wn6","title":"Real Numbers: Decimals and Cyclic Patterns","icon":"🔁","kind":"lesson","story":"Unite the dense web of rational numbers with the unfillable gaps of the irrationals, and you get one unbroken line: the Real Numbers. The secret to telling them apart, it turns out, is hiding in their decimal expansions.","teach":[{"title":"Terminating and Repeating Decimals","body":"Dividing the numerator of a rational number by its denominator either terminates, like 3/8 = 0.375, or repeats forever in a loop, like 5/11 = 0.454545… A rational number's decimal terminates exactly when the prime factors of its denominator (in lowest form) are only 2, only 5, or both.","visual":"⚖️"},{"title":"Converting Repeating Decimals Back to p/q","body":"To convert a pure repeating decimal like x = 0.6-repeating (0.666…), multiply by 10 to get 10x = 6.6-repeating, then subtract: 9x = 6, so x = 2/3. The same subtraction trick works for decimals with a non-repeating part followed by a repeating block.","visual":"🔢"},{"title":"Cyclic Numbers and Irrational Chaos","body":"The repeating block of 1/7, which is 142857, is a cyclic number: multiplying it by 1 through 6 just cycles the same six digits (142857 × 3 = 428571). Irrational numbers, by contrast, have decimal expansions that never terminate and never repeat, like √2 = 1.4142135… and π = 3.1415926…","visual":"🌀"}],"questions":[{"kind":"mcq","prompt":"A rational number's decimal expansion will terminate exactly when the prime factors of its denominator (in lowest form) are","options":["only 2, only 5, or both 2 and 5","only 2 and 3","only prime numbers greater than 5","any even number"],"answer":0,"explain":"Denominators whose only prime factors are 2 and/or 5 can be converted to a power of 10, giving a terminating decimal."},{"kind":"numeric","prompt":"What is 3/8 written as a decimal?","answer":0.375,"explain":"Dividing 3 by 8 terminates exactly at 0.375."},{"kind":"mcq","prompt":"Converting x = 0.6-repeating (0.666…) into the form p/q gives","options":["2/3","6/10","3/5","3/4"],"answer":0,"explain":"10x − x = 6.6-repeating − 0.6-repeating = 6, so 9x = 6, giving x = 2/3."},{"kind":"mcq","prompt":"What special property does 142857, the repeating block of 1/7, have?","options":["Multiplying it by 1 through 6 cycles the same six digits","It is a prime number","It only appears when dividing by 11","It terminates after six digits"],"answer":0,"explain":"142857 × 1 through 142857 × 6 all produce the same six digits shifted cyclically."},{"kind":"mcq","prompt":"Which of these decimal expansions belongs to an irrational number?","options":["1.4142135623… (never terminates, never repeats)","0.375 (terminates)","0.454545… (repeats)","0.16666… (repeats)"],"answer":0,"explain":"Only a non-terminating, non-repeating decimal like √2 = 1.4142135623… signals an irrational number."}]},{"id":"wn-boss","title":"Guardian of the Number Line","icon":"🐉","kind":"boss","story":"Every idea you've learned — counting, zero, debts, fractions, and the unfillable gaps of the irrationals — has built the unbroken Real Number Line. Now the Guardian of the Number Line rises to test whether you truly command this entire world.","boss":{"name":"The Number Line Guardian","taunt":"You have counted bones and conquered debts — but can you hold the whole line, rational and irrational, in one hand?"},"teach":[{"title":"The Hierarchy of Numbers","body":"Natural Numbers (N) sit inside Integers (Z), which sit inside Rational Numbers (ℚ), which combine with the Irrational Numbers to form the Real Numbers (ℝ) — one continuous, unbroken line where every real measurement has a home.","visual":"🗺️"},{"title":"Beyond the Real Line","body":"There is no real number that, when multiplied by itself, gives a negative number — so √−1 cannot exist on the number line. Mathematicians invented Imaginary Numbers, denoted i, to step off the line entirely, a story for a later year.","visual":"✨"}],"questions":[{"kind":"mcq","prompt":"Natural numbers are closed under addition. Are they closed under subtraction?","options":["No — for example, 3 − 5 is not a natural number","Yes — subtraction of any two natural numbers is always natural","Yes, but only for numbers greater than 10","No natural numbers can ever be subtracted"],"answer":0,"explain":"3 − 5 = −2, which is not a natural number, so natural numbers are not closed under subtraction."},{"kind":"numeric","prompt":"Using Brahmagupta's rules, what is (–8) × (–7)?","answer":56,"explain":"The product of two debts is a fortune: (–8) × (–7) = 56."},{"kind":"mcq","prompt":"Which symbol denotes the set of rational numbers?","options":["ℚ","Z","N","ℝ"],"answer":0,"explain":"ℚ (for 'quotient') denotes the set of all rational numbers p/q."},{"kind":"numeric","prompt":"What is 0 − (−14)?","answer":14,"explain":"Subtracting a negative is the same as adding its positive: 0 − (−14) = 0 + 14 = 14."},{"kind":"mcq","prompt":"Which mathematician gave the first formal arithmetic rules for zero, in 628 CE?","options":["Brahmagupta","Āryabhaṭa","Hippasus","Mādhava of Sangamagrama"],"answer":0,"explain":"Brahmagupta's Brāhmasphuṭasiddhānta (628 CE) gave the first formal rules for arithmetic with zero."},{"kind":"mcq","prompt":"The Real Numbers (ℝ) are formed by combining which two sets?","options":["Rational numbers and irrational numbers","Natural numbers and integers only","Only positive and negative integers","Fractions and imaginary numbers"],"answer":0,"explain":"Uniting the rational numbers with the irrational numbers produces the complete, unbroken real number line."},{"kind":"mcq","prompt":"Why can't √−1 exist on the real number line?","options":["Because no real number multiplied by itself gives a negative result","Because −1 is not an integer","Because negative numbers have no square roots at all","Because the number line only contains positive numbers"],"answer":0,"explain":"Both positive and negative real numbers give a positive result when squared, so no real number squares to −1."}]}]},{"id":"identities9","index":3,"name":"Exploring Algebraic Identities","subtitle":"Ganita Manjari Chapter 4","emoji":"🧮","palette":{"from":"#4ade80","to":"#14532d"},"lessons":[{"id":"ai1","title":"The Squares That Always Work","icon":"🟩","kind":"lesson","story":"Take three consecutive square numbers like 1, 4, 9 — add the smallest and largest, subtract twice the middle one, and you always land on 2. That's no accident: it's an algebraic identity hiding in plain sight, and you're about to unlock the two identities that explain patterns like this.","teach":[{"title":"Identity vs Equation","body":"An algebraic identity is an equation that is true for ALL values of its variables, unlike a plain equation which may hold only for specific values. For example, x² - 1 = 24 is true only when x = 5 or x = -5, so it's an equation — but (x+y)² = x² + 2xy + y² holds for every x and y, so it's an identity.","visual":"🟰"},{"title":"(a+b)² = a² + 2ab + b²","body":"Picture a square of side (a+b) split into a square of side a, a square of side b, and two rectangles of area ab each. Adding all four pieces gives (a+b)² = a² + 2ab + b², and this holds true even when a and b are negative or fractions.","visual":"⬜"},{"title":"(a-b)² = a² - 2ab + b²","body":"Replacing b with -b in the identity above gives (a-b)² = a² - 2ab + b². Geometrically, split a square of side a into a piece of length (a-b) and a piece of length b; subtracting the two connecting rectangles from the big square's area a² leaves exactly a² - 2ab + b².","visual":"🔲"},{"title":"Speedy Squaring","body":"These identities turn hard multiplications into easy addition. To find 43², write 43 = 40+3, so 43² = 40² + 2(40)(3) + 3² = 1600+240+9 = 1849. To find 29², write 29 = 30-1, so 29² = 30² - 2(30)(1) + 1² = 900-60+1 = 841.","visual":"⚡"}],"questions":[{"kind":"mcq","prompt":"Which of these is a genuine algebraic identity — true for every value of the variables?","options":["(x+y)² = x² + 2xy + y²","x² - 1 = 24","x + 5 = 12","2x = 10"],"answer":0,"explain":"It holds for all x and y, while the others are equations true only for particular values."},{"kind":"numeric","prompt":"Using (a+b)² = a²+2ab+b² with a=40, b=3, what is 43²?","answer":1849,"explain":"40²+2(40)(3)+3² = 1600+240+9 = 1849."},{"kind":"numeric","prompt":"Using (a-b)² = a²-2ab+b² with a=30, b=1, what is 29²?","answer":841,"explain":"30²-2(30)(1)+1² = 900-60+1 = 841."},{"kind":"mcq","prompt":"Expand (5x+2y)² using the identity (a+b)² = a²+2ab+b².","options":["25x²+20xy+4y²","25x²+10xy+4y²","5x²+20xy+2y²","25x²+20xy+2y²"],"answer":0,"explain":"a=5x, b=2y so a²=25x², 2ab=2(5x)(2y)=20xy, b²=4y²."},{"kind":"numeric","prompt":"Take three consecutive square numbers 25, 36, 49 (squares of 5, 6, 7). Add the smallest and largest, then subtract twice the middle one: (25+49) - 2×36. What do you get?","answer":2,"explain":"This always equals 2, since (n-1)²+(n+1)²-2n² = 2 for any n."}]},{"id":"ai2","title":"Three Terms and an Ancient Trick","icon":"🧩","kind":"lesson","story":"What happens when you square not two, but three numbers added together — like (a+b+c)²? And centuries before calculators, the mathematician Śhrīdharāchārya found a lightning-fast way to square numbers using nothing but a clever identity. Time to steal his trick.","teach":[{"title":"(a+b+c)² = a²+b²+c²+2ab+2bc+2ca","body":"Replace b with (b+c) in (a+d)² = a²+2ad+d² to derive this three-term identity. It can also be proved geometrically using a square of side (a+b+c) split into three squares and six rectangles.","visual":"🟪"},{"title":"Squaring big numbers with three parts","body":"119 = 100+10+9, so 119² = 100²+10²+9²+2(100)(10)+2(100)(9)+2(10)(9) = 10000+100+81+2000+1800+180 = 14161.","visual":"🔢"},{"title":"The Difference of Squares: a² - b² = (a+b)(a-b)","body":"This identity, studied since Grade 8, can be rewritten as a² = (a+b)(a-b) + b². In 750 CE the mathematician Śhrīdharāchārya used exactly this rearrangement to square numbers quickly.","visual":"📜"},{"title":"Śhrīdharāchārya's shortcut","body":"To find 55², pick b=5 so that a+b=60 and a-b=50 are easy to multiply: 55² = (55+5)(55-5) + 5² = 60×50+25 = 3000+25 = 3025.","visual":"✨"}],"questions":[{"kind":"numeric","prompt":"Using (a+b+c)² with a=100, b=10, c=9, compute 119².","answer":14161,"explain":"100²+10²+9²+2(100)(10)+2(100)(9)+2(10)(9) = 10000+100+81+2000+1800+180 = 14161."},{"kind":"mcq","prompt":"Which identity correctly expands (p+3q+7r)²?","options":["p²+9q²+49r²+6pq+42qr+14pr","p²+3q²+7r²+2pq+2qr+2pr","p²+9q²+49r²+3pq+7qr+21pr","p²+9q²+49r²+6pq+21qr+42pr"],"answer":0,"explain":"With a=p, b=3q, c=7r: a²+b²+c²+2ab+2bc+2ca = p²+9q²+49r²+6pq+42qr+14pr."},{"kind":"numeric","prompt":"Using Śhrīdharāchārya's identity a² = (a+b)(a-b)+b² with a=55, b=5, what is 55²?","answer":3025,"explain":"(55+5)(55-5)+5² = 60×50+25 = 3025."},{"kind":"numeric","prompt":"Using the same trick with a=35, b=5, find 35².","answer":1225,"explain":"(35+5)(35-5)+5² = 40×30+25 = 1200+25 = 1225."},{"kind":"mcq","prompt":"The identity a² - b² = (a+b)(a-b) can be rearranged to compute squares as:","options":["a² = (a+b)(a-b) + b²","a² = (a+b)(a-b) - b²","a² = (a-b)(a-b) + b²","a² = 2(a+b)(a-b)"],"answer":0,"explain":"Adding b² to both sides of a²-b² = (a+b)(a-b) isolates a² on one side."}]},{"id":"ai3","title":"Cracking Factors Open","icon":"🔓","kind":"lesson","story":"Saira built a rectangle out of a big x-by-x square, eight x-by-1 strips, and fifteen unit squares — and its total area, x²+8x+15, hides the rectangle's exact length and breadth. Learning to factor expressions like this turns messy algebra into neatly labeled building blocks.","teach":[{"title":"Spotting a perfect square trinomial","body":"If an expression matches a²+2ab+b², it factors as (a+b)². For example, x²+4x+4 = x²+2(x)(2)+2² = (x+2)², and 36x²+12x+1 = (6x)²+2(6x)(1)+1² = (6x+1)².","visual":"🔍"},{"title":"Taking out a common factor first","body":"50p²+60pq+18q² has a common factor of 2: 2(25p²+30pq+9q²) = 2[(5p)²+2(5p)(3q)+(3q)²] = 2(5p+3q)².","visual":"🧮"},{"title":"Splitting the middle term","body":"To factor x²+7x+12, write it as x²+(a+b)x+ab and find a,b with a+b=7 and ab=12 — that's a=3, b=4, giving (x+3)(x+4). For x²+11x+30, we need a+b=11 and ab=30, satisfied by a=5, b=6, giving (x+5)(x+6). Algebra tiles show this visually: the x-tiles literally get split into two groups to form a rectangle.","visual":"🟨"},{"title":"Simplifying rational expressions","body":"Factor the top and bottom, then cancel any common factor (as long as it isn't zero). For (x²-7x+12)/(5x²+5x-100): the numerator factors as (x-3)(x-4) and the denominator as 5(x-4)(x+5), so cancelling (x-4) leaves (x-3)/(5(x+5)).","visual":"➗"}],"questions":[{"kind":"mcq","prompt":"Factor x²+4x+4 completely.","options":["(x+2)²","(x+4)²","(x+2)(x+4)","(x-2)²"],"answer":0,"explain":"x²+4x+4 = x²+2(x)(2)+2² = (x+2)²."},{"kind":"mcq","prompt":"Factor 36x²+12x+1.","options":["(6x+1)²","(6x+1)(6x-1)","(12x+1)²","(6x+2)²"],"answer":0,"explain":"36x²+12x+1 = (6x)²+2(6x)(1)+1² = (6x+1)²."},{"kind":"mcq","prompt":"Factor x²+11x+30 by splitting the middle term.","options":["(x+5)(x+6)","(x+3)(x+10)","(x+2)(x+15)","(x+1)(x+30)"],"answer":0,"explain":"We need a+b=11 and ab=30; only a=5, b=6 satisfies both."},{"kind":"numeric","prompt":"In x²-5x+6 = x²+(a+b)x+ab, what is the value of a+b?","answer":-5,"explain":"Comparing coefficients of x gives a+b=-5 (with a=-2, b=-3, since ab=6)."},{"kind":"mcq","prompt":"After factoring, (x²-7x+12)/(5x²+5x-100) simplifies to:","options":["(x-3)/(5(x+5))","(x-4)/(5(x+5))","(x-3)/(5(x-4))","(x-3)(x-4)/5"],"answer":0,"explain":"Numerator = (x-3)(x-4), denominator = 5(x-4)(x+5); cancelling (x-4) leaves (x-3)/(5(x+5))."}]},{"id":"ai4","title":"Into the Third Dimension","icon":"📦","kind":"lesson","story":"Squares live in two dimensions, but what if you stack a cube of edge (a+b)? Slicing it apart reveals a brand new identity — and once you have cubes in your toolkit, you can solve puzzles like finding the sum of three numbers' cubes just from their sum, product, and sum of squares.","teach":[{"title":"(a+b)³ = a³+3a²b+3ab²+b³","body":"Multiply out (a+b)(a²+2ab+b²) using distributivity to get this cubic identity. Geometrically, a cube of edge (a+b) splits into two smaller cubes (volumes a³ and b³) plus six cuboids (three with volume a²b, three with volume ab²).","visual":"🧊"},{"title":"(a-b)³ = a³-3a²b+3ab²-b³","body":"Replacing b with -b in the identity above gives (a-b)³ = a³-3a²b+3ab²-b³, where the positive and negative terms alternate.","visual":"🎲"},{"title":"Sum and difference of cubes","body":"Multiplying out (x-y)(x²+xy+y²) gives x³-y³, and multiplying (x+y)(x²-xy+y²) gives x³+y³. So x³-y³ = (x-y)(x²+xy+y²) and x³+y³ = (x+y)(x²-xy+y²).","visual":"➕"},{"title":"The three-cubes identity","body":"Multiplying (x+y+z) by (x²+y²+z²-xy-xz-yz) gives x³+y³+z³-3xyz. This solves tricky problems: if three numbers have sum 10, product 25, and sum of squares 38, substituting into this identity together with (x+y+z)²=x²+y²+z²+2(xy+xz+yz) reveals xy+xz+yz=31, and finally x³+y³+z³ = 455-10(31) = 145.","visual":"🎯"}],"questions":[{"kind":"mcq","prompt":"Which is the correct expansion of (a-b)³?","options":["a³-3a²b+3ab²-b³","a³+3a²b+3ab²+b³","a³-3a²b-3ab²-b³","a³-b³"],"answer":0,"explain":"Replacing b with -b in (a+b)³ = a³+3a²b+3ab²+b³ flips the sign of every odd power of b."},{"kind":"mcq","prompt":"The expression p³+6p²q+12pq²+8q³ is the cube of which binomial?","options":["(p+2q)","(p+6q)","(2p+q)","(p+8q)"],"answer":0,"explain":"Matching with a³+3a²b+3ab²+b³ gives a=p, b=2q, since 3a²b=6p²q, 3ab²=12pq², b³=8q³."},{"kind":"mcq","prompt":"8n³-60n²m+150nm²-125m³ is the cube of which binomial?","options":["(2n-5m)","(2n-25m)","(8n-125m)","(2n+5m)"],"answer":0,"explain":"Comparing with a³-3a²b+3ab²-b³ gives a=2n, b=5m: (2n)³-3(2n)²(5m)+3(2n)(5m)²-(5m)³."},{"kind":"numeric","prompt":"Three numbers satisfy x+y+z=10, xyz=25, and x²+y²+z²=38. Using (x+y+z)² = x²+y²+z²+2(xy+xz+yz), find xy+xz+yz.","answer":31,"explain":"100 = 38+2(xy+xz+yz), so xy+xz+yz = (100-38)/2 = 31."},{"kind":"numeric","prompt":"Continuing the same problem, use x³+y³+z³-3xyz = (x+y+z)(x²+y²+z²-xy-xz-yz) to find x³+y³+z³.","answer":145,"explain":"10(38-31)+3(25) = 10(7)+75 = 70+75 = 145."}]},{"id":"ai-boss","title":"The Identity Keeper","icon":"👑","kind":"boss","story":"All the identities you've collected — squares, three-term squares, difference of squares, factoring tricks, and cubes — now face their final test. The Identity Keeper guards the chapter's secrets and won't step aside until you prove every tool is sharp.","boss":{"name":"The Identity Keeper","taunt":"Every equation bends to identities — prove you've mastered them all, or be lost in the algebra maze forever!"},"teach":[],"questions":[{"kind":"mcq","prompt":"Expand (2s+7)(2s-7) using a²-b² = (a+b)(a-b).","options":["4s²-49","4s²+49","2s²-49","4s-49"],"answer":0,"explain":"a=2s, b=7: (2s)²-7² = 4s²-49."},{"kind":"numeric","prompt":"Using (a-b)² = a²-2ab+b² with a=100, b=1, find 99².","answer":9801,"explain":"100²-2(100)(1)+1² = 10000-200+1 = 9801."},{"kind":"mcq","prompt":"Factor 16y²-24y+9.","options":["(4y-3)²","(4y+3)²","(4y-3)(4y+3)","(8y-3)²"],"answer":0,"explain":"16y²-24y+9 = (4y)²-2(4y)(3)+3² = (4y-3)²."},{"kind":"numeric","prompt":"A rectangular pool's breadth is 4 m less than its length, and its area is 96 sq m. Writing the length as x, the equation x²-4x-96=0 factors as (x-12)(x+8)=0. What is the length of the pool, in metres?","answer":12,"explain":"x=12 is chosen over x=-8 since a length can't be negative; the breadth is then 12-4=8 m."},{"kind":"mcq","prompt":"Which correctly states the identity for (x+a)(x+b)?","options":["x²+(a+b)x+ab","x²+ab·x+(a+b)","x²+(a-b)x+ab","x²+(a+b)x-ab"],"answer":0,"explain":"Expanding by distributivity: x(x+b)+a(x+b) = x²+bx+ax+ab = x²+(a+b)x+ab."},{"kind":"numeric","prompt":"Use (a+b)³ = a³+3a²b+3ab²+b³ with a=10, b=1 to compute 11³.","answer":1331,"explain":"10³+3(10²)(1)+3(10)(1²)+1³ = 1000+300+30+1 = 1331."}]}]},{"id":"symmetry9","index":4,"name":"I'm Up and Down, and Round and Round","subtitle":"Ganita Manjari Chapter 5 — Circles","emoji":"🎡","palette":{"from":"#38bdf8","to":"#0c4a6e"},"lessons":[{"id":"sy1","title":"The Shape With a Secret Centre","icon":"⭕","kind":"lesson","story":"Cave painters at Gudahandi scratched circles into rock beside their triangles and squares — echoes of the sun, the full moon, and ripples spreading on still water. Every one of those round shapes hides the same secret: one centre point, the same distance from every edge. Find that secret and you unlock this whole chapter.","teach":[{"title":"What exactly is a circle?","body":"A circle is the set of all points in a plane that are equidistant from one fixed point — its centre. This set of points is also called the locus of points equidistant from the centre. The distance from the centre to any point on the circle is the radius.","visual":"🎯"},{"title":"Chords and diameters","body":"A line segment joining two points on a circle is called a chord. A chord that passes through the centre is called a diameter — since it stretches all the way across through the centre, it is the longest possible chord of the circle.","visual":"📏"},{"title":"A circle's perfect symmetry","body":"A circle has reflection symmetry across every one of its diameters — fold a paper circle so the edges meet exactly and the crease is always a diameter. It also has complete rotational symmetry: rotate it by any angle about its centre and it looks exactly the same, like a spinning wheel.","visual":"🔄"}],"questions":[{"kind":"mcq","prompt":"How is a circle formally defined in geometry?","options":["the locus of all points in a plane equidistant from one fixed point","the set of all points inside a fixed boundary","a shape with four equal sides","the path traced by a moving straight line"],"answer":0,"explain":"A circle is the locus (set) of points at a fixed distance — the radius — from a fixed centre."},{"kind":"mcq","prompt":"A chord that passes through the centre of a circle is called a...","options":["diameter","radius","tangent","arc"],"answer":0,"explain":"A chord passing through the centre is a diameter, and it is the longest chord possible in the circle."},{"kind":"mcq","prompt":"How many lines of reflection symmetry does a circle have?","options":["infinitely many — every diameter is one","exactly 4","exactly 1","none"],"answer":0,"explain":"Every diameter of a circle is a line of reflection symmetry, and a circle has infinitely many diameters."},{"kind":"numeric","prompt":"A circle has radius 9 units. What is the length of its longest possible chord (the diameter), in units?","answer":18,"explain":"The diameter is twice the radius: 2 × 9 = 18."}]},{"id":"sy2","title":"One Circle to Rule Three Points","icon":"📐","kind":"lesson","story":"A wheelwright is given two nail-marks on a plank and told to cut a perfectly circular wheel through both. She quickly realises there isn't just one way to do it — infinitely many circles pass through two points. But add a third point, and suddenly only one circle will ever do.","teach":[{"title":"Infinite circles through two points","body":"Given two points A and B, any point equidistant from both can serve as the centre of a circle through A and B. All such points lie on the perpendicular bisector of AB, so infinitely many circles pass through any two points — with the smallest one having AB itself as a diameter.","visual":"➗"},{"title":"The circumcircle of a triangle","body":"For any three non-collinear points A, B, C, there is exactly one circle passing through all three (Theorem 1). Its centre — the circumcentre — is the point where the perpendicular bisectors of AB, BC, and AC all meet. This circle is the circumcircle of triangle ABC, and the triangle is said to be inscribed in it.","visual":"🔺"},{"title":"Where does the circumcentre live?","body":"The circumcentre's position depends on the triangle's shape: it lies inside an acute-angled triangle, outside an obtuse-angled triangle, and exactly at the midpoint of the hypotenuse of a right-angled triangle.","visual":"📍"}],"questions":[{"kind":"mcq","prompt":"The centres of all possible circles passing through two fixed points A and B lie on...","options":["the perpendicular bisector of AB","the line segment AB itself","a circle centred at A","a line through A parallel to AB"],"answer":0,"explain":"Any centre must be equidistant from A and B, and that locus is exactly the perpendicular bisector of AB."},{"kind":"mcq","prompt":"How many circles pass through three given non-collinear points?","options":["exactly one — the circumcircle","exactly two","infinitely many","none, unless they form a right angle"],"answer":0,"explain":"Theorem 1 states there is a unique circle passing through any three non-collinear points."},{"kind":"mcq","prompt":"In a right-angled triangle, where does the circumcentre lie?","options":["at the midpoint of the hypotenuse","exactly at the right-angle vertex","always outside the triangle","at the triangle's centroid"],"answer":0,"explain":"For a right-angled triangle, the circumcentre sits exactly at the midpoint of the hypotenuse."},{"kind":"mcq","prompt":"Why is there no circle passing through three collinear points?","options":["the perpendicular bisectors of the segments they form are parallel and never meet","circles cannot have three points on them","collinear points are always too far apart","a circle can only ever pass through two points"],"answer":0,"explain":"For collinear points, the perpendicular bisectors of the two segments they form are parallel, so they never intersect to give a centre."}]},{"id":"sy3","title":"Chords, Congruence, and the Centre's Reach","icon":"🧵","kind":"lesson","story":"Tie a thread tightly between two points on a bicycle wheel's rim — that thread is a chord. Spin the wheel, and the thread rotates to a new position but keeps the exact same length and the exact same angle at the centre. That stubborn consistency is what this lesson is all about.","teach":[{"title":"Equal chords, equal angles","body":"Equal chords of a circle subtend equal angles at the centre (Theorem 2), and conversely, chords that subtend equal angles at the centre are themselves equal in length (Theorem 3). Both follow from SSS/SAS congruence of the triangles formed by the two radii and the chord.","visual":"🔺"},{"title":"The centre's perpendicular","body":"The line joining the centre of a circle to the midpoint of a chord is always perpendicular to that chord (Theorem 4). Conversely, the perpendicular dropped from the centre to a chord always bisects the chord (Theorem 5).","visual":"⊥"},{"title":"Distance from the centre","body":"Chords of equal length are always equidistant from the centre, and chords equidistant from the centre are always equal in length (Theorems 6 and 7). Between two unequal chords, the longer one is always closer to the centre — the diameter, being the longest chord, sits at distance zero (Theorem 8).","visual":"📏"},{"title":"Chord length from radius and distance","body":"The radius, half the chord, and the perpendicular distance from the centre form a right triangle. By the Baudhāyana–Pythagoras theorem, chord length = 2√(r² − d²), where r is the radius and d is the distance from the centre to the chord.","visual":"➕"}],"questions":[{"kind":"mcq","prompt":"If two chords of a circle are equal in length, what must be true of the angles they subtend at the centre?","options":["they must be equal","they must add up to 180°","they must be supplementary","nothing can be said about them"],"answer":0,"explain":"Equal chords always subtend equal angles at the centre (Theorem 2)."},{"kind":"mcq","prompt":"The line from a circle's centre to the midpoint of a chord is always...","options":["perpendicular to the chord","parallel to the chord","equal in length to the chord","half the length of the chord"],"answer":0,"explain":"Theorem 4 shows this line is always perpendicular to the chord, since it splits an isosceles triangle into two congruent right triangles."},{"kind":"mcq","prompt":"Between two unequal chords of the same circle, which one lies closer to the centre?","options":["the longer chord","the shorter chord","both lie at the same distance","it depends on the circle's radius"],"answer":0,"explain":"Theorem 8 shows the longer chord is always the one closer to the centre."},{"kind":"numeric","prompt":"A chord lies 5 cm from the centre of a circle of radius 13 cm. What is the length of the chord, in cm?","answer":24,"explain":"Half the chord = √(13² − 5²) = √(169−25) = √144 = 12, so the full chord = 2 × 12 = 24 cm."},{"kind":"numeric","prompt":"A chord of length 16 cm lies 6 cm from the centre of a circle. What is the radius of the circle, in cm?","answer":10,"explain":"Half the chord is 8 cm, and radius = √(8² + 6²) = √(64+36) = √100 = 10 cm."}]},{"id":"sy4","title":"What Angles Do Arcs Whisper?","icon":"🌓","kind":"lesson","story":"Picture a giant Ferris wheel. Riders sitting at completely different points on the rim all look back at the same two boarding points — and no matter where they're sitting on the far side, they see the exact same angle between them. That's the secret language of arcs.","teach":[{"title":"Major and minor arcs","body":"Two points A and B on a circle split it into two arcs. The bigger portion is the major arc and the smaller portion is the minor arc. The angle subtended by an arc at the centre is the angle swept moving from one radius to the other along that arc.","visual":"🌗"},{"title":"Centre angle vs circle angle","body":"Theorem 9: the angle an arc subtends at the centre of the circle is always double the angle it subtends at any point on the circle lying outside that arc. This holds no matter which outside point is picked, so all such angles 'in the same segment' are equal to each other.","visual":"✖️2"},{"title":"The angle in a semicircle","body":"A diameter splits a circle into two equal arcs, each subtending a straight angle (180°) at the centre. By the corollary to Theorem 9, the angle subtended by a diameter at any point on the circle is therefore always 90°.","visual":"📐"}],"questions":[{"kind":"mcq","prompt":"The angle subtended by an arc at the centre of a circle is always ___ the angle it subtends at a point on the remaining part of the circle.","options":["double","equal to","half of","triple"],"answer":0,"explain":"Theorem 9 states the central angle is exactly twice the angle subtended at any point on the remaining circle."},{"kind":"numeric","prompt":"A central angle AOB measures 60°. What is the angle subtended by the same arc AB at a point on the major arc, in degrees?","answer":30,"explain":"The angle at the circle is half the central angle: 60° ÷ 2 = 30°."},{"kind":"mcq","prompt":"What is the angle subtended by a diameter at any point on the circle (other than its endpoints)?","options":["90°","180°","60°","45°"],"answer":0,"explain":"A diameter subtends a straight angle (180°) at the centre, so by Theorem 9 it subtends half of that, 90°, at the circle."},{"kind":"mcq","prompt":"Points D and E both lie on a circle, outside a given arc AB. How do the angles ∠ADB and ∠AEB compare?","options":["they are always equal","they are always supplementary","∠ADB is always double ∠AEB","they cannot be compared"],"answer":0,"explain":"All angles subtended by the same arc at points on the remaining part of the circle are equal."},{"kind":"numeric","prompt":"An arc subtends an angle of 70° at the centre. What angle does it subtend at a point on the circle outside the arc, in degrees?","answer":35,"explain":"The angle at the circle is half the central angle: 70° ÷ 2 = 35°."}]},{"id":"sy5","title":"Four Points, One Circle","icon":"🔲","kind":"lesson","story":"Four friends stand scattered across a field. A surveyor claims she can draw one single circle passing through every one of them — but only if their angles agree in a very particular way. This is the mathematics of concyclic points.","teach":[{"title":"When four points share a circle","body":"Points that lie on the same circle are called concyclic. Theorem 10: if a segment AB subtends equal angles at two other points C and D on the same side of AB, then A, B, C, and D are concyclic — all four lie on one circle.","visual":"🔗"},{"title":"Cyclic quadrilaterals","body":"A quadrilateral whose four vertices are concyclic (lie on a single circle) is called a cyclic quadrilateral. Theorem 11: the sum of each pair of opposite angles in a cyclic quadrilateral is always 180°.","visual":"🔲"},{"title":"The converse also holds","body":"Theorem 12: if the two pairs of opposite angles of a quadrilateral each add up to 180°, then that quadrilateral must be cyclic — its vertices all lie on a single circle.","visual":"🔁"}],"questions":[{"kind":"mcq","prompt":"Points that all lie on the same circle are called...","options":["concyclic","collinear","congruent","coplanar"],"answer":0,"explain":"Points lying on one common circle are called concyclic."},{"kind":"mcq","prompt":"In a cyclic quadrilateral, each pair of opposite angles always adds up to...","options":["180°","360°","90°","120°"],"answer":0,"explain":"Theorem 11 shows opposite angles of a cyclic quadrilateral are always supplementary, summing to 180°."},{"kind":"numeric","prompt":"In cyclic quadrilateral ABCD, ∠A measures 75°. What is the measure of ∠C, in degrees?","answer":105,"explain":"Opposite angles of a cyclic quadrilateral sum to 180°, so ∠C = 180° − 75° = 105°."},{"kind":"numeric","prompt":"In the same cyclic quadrilateral, ∠B measures 110°. What is the measure of ∠D, in degrees?","answer":70,"explain":"Opposite angles sum to 180°, so ∠D = 180° − 110° = 70°."},{"kind":"mcq","prompt":"If two opposite angles of a quadrilateral add up to 180°, what can you conclude?","options":["the quadrilateral is cyclic — its vertices lie on one circle","the quadrilateral is a rectangle","the quadrilateral has no circle through its vertices","nothing can be concluded"],"answer":0,"explain":"Theorem 12, the converse of Theorem 11, guarantees the quadrilateral is cyclic."}]},{"id":"sy-boss","title":"The Round Table's Final Trial","icon":"🐉","kind":"boss","boss":{"name":"Vritta, the Ever-Turning Guardian","taunt":"You think you understand circles? Prove it, or spin in my shadow forever!"},"story":"At the heart of the ancient circle temple sits Vritta, the guardian who has watched wheels, moons, and wells turn for a thousand years. To pass, you must prove mastery over every secret this chapter revealed — chords, circumcircles, arcs, and cyclic quadrilaterals, all at once.","teach":[],"questions":[{"kind":"numeric","prompt":"A chord lies 6 cm from the centre of a circle of radius 10 cm. What is the length of the chord, in cm?","answer":16,"explain":"Half the chord = √(10²−6²) = √(100−36) = √64 = 8, so the full chord = 2 × 8 = 16 cm."},{"kind":"mcq","prompt":"AB is a diameter of a circle and C is a point on the circumference. What is the measure of ∠ACB?","options":["90°","180°","60°","it depends on where C is"],"answer":0,"explain":"The angle subtended by a diameter at any point on the circle is always 90°, regardless of where C sits on the circle."},{"kind":"numeric","prompt":"PQRS is a cyclic quadrilateral with ∠P = (2x + 10)° and ∠R = (3x − 20)°. Since ∠P and ∠R are opposite angles, find x.","answer":38,"explain":"Opposite angles of a cyclic quadrilateral sum to 180°: (2x+10)+(3x−20)=180, so 5x−10=180, 5x=190, x=38."},{"kind":"numeric","prompt":"A circle has diameter 26 cm. A chord of length 24 cm is drawn in it. What is the distance from the centre to the chord, in cm?","answer":5,"explain":"The radius is 13 cm and half the chord is 12 cm. Distance = √(13²−12²) = √(169−144) = √25 = 5 cm."},{"kind":"mcq","prompt":"What is the circumcentre of a triangle?","options":["the point equidistant from all three vertices, where the perpendicular bisectors of the sides meet","the point where the three medians meet","the midpoint of the longest side","the point inside the triangle closest to all three sides"],"answer":0,"explain":"The circumcentre is defined as the centre of the circumcircle — the intersection of the perpendicular bisectors of the triangle's sides, equidistant from all three vertices."},{"kind":"mcq","prompt":"Two chords of the same circle are equidistant from the centre. What must be true about their lengths?","options":["they are equal in length","one must be exactly double the other","they must be perpendicular to each other","nothing can be concluded about their lengths"],"answer":0,"explain":"Theorem 7 states that chords equidistant from the centre of a circle are always equal in length."}]}]},{"id":"mensuration9","index":5,"name":"Measuring Space","subtitle":"Ganita Manjari Chapter 6 — Perimeter and Area","emoji":"📐","palette":{"from":"#facc15","to":"#713f12"},"lessons":[{"id":"ms1","title":"The Runner's Edge","icon":"🏃","kind":"lesson","story":"The relay race is about to start, and something looks wrong — the runners in the outer lanes are standing metres ahead of the ones in the inside lane! Before you can call foul, your coach grins: 'It's not a head start — it's math.' To understand the stagger, you must first master the oldest measurement of all: the perimeter.","teach":[{"title":"What Is Perimeter?","body":"The perimeter of a shape is the total length around its border. Imagine a tiny insect walking around the edge of a shape, never turning back, until it returns to its starting point — the distance it travels is the perimeter.","visual":"🐜"},{"title":"Squares and Equilateral Triangles","body":"A square with side a units has perimeter 4a units. An equilateral triangle with side a units has perimeter 3a units. As the side grows or shrinks, the ratio of perimeter to side stays fixed — 4:1 for every square, 3:1 for every equilateral triangle.","visual":"🔺"},{"title":"Rectangles","body":"A rectangle with length a units and width b units has perimeter 2(a + b) units. The perimeter formula for a square is just a special case of this, obtained by setting a = b.","visual":"▭"}],"questions":[{"kind":"numeric","prompt":"Find the perimeter (in cm) of a square with side 9 cm.","answer":36,"explain":"Perimeter of a square = 4 × side = 4 × 9 = 36 cm."},{"kind":"numeric","prompt":"Find the perimeter (in cm) of an equilateral triangle with side 12 cm.","answer":36,"explain":"Perimeter of an equilateral triangle = 3 × side = 3 × 12 = 36 cm."},{"kind":"numeric","prompt":"Find the perimeter (in m) of a rectangle with length 15 m and width 9 m.","answer":48,"explain":"Perimeter of a rectangle = 2(a + b) = 2(15 + 9) = 2 × 24 = 48 m."},{"kind":"mcq","prompt":"For squares of any size, the ratio of perimeter to side length is always...","options":["4:1","It changes with the size of the square","3:1","It depends on the unit used"],"answer":0,"explain":"Since perimeter = 4a and side = a, the ratio perimeter:side = 4:1 for every square, regardless of size."},{"kind":"mcq","prompt":"The perimeter formula for a square (4a) is a special case of the perimeter formula for a rectangle (2(a+b)) obtained by setting...","options":["a = b","a = 2b","a + b = 4","b = 0"],"answer":0,"explain":"A square is a rectangle whose two adjacent sides are equal, so putting a = b in 2(a+b) gives 2(2a) = 4a."}]},{"id":"ms2","title":"Chasing the Ratio","icon":"🥧","kind":"lesson","story":"Deep in an ancient workshop, a mathematician wraps a thin thread twenty times around a wooden reel, unwinds it, and measures its length. No matter which reel she tries, the thread's length divided by twenty diameters always comes out close to the same mysterious number. You're about to chase that number — π — across three thousand years of human curiosity.","teach":[{"title":"The C/D Ratio","body":"For any circle, the ratio of its circumference (C) to its diameter (D) never changes, no matter the size of the circle. This fixed ratio is called π (pi) — named because π is the first letter of the Greek word 'perimetros', for perimeter.","visual":"🔵"},{"title":"Ancient Approximations","body":"Mesopotamians (c. 1900 BCE) used π ≈ 3 + 1/8 = 3.125. Archimedes (250 BCE) trapped π between 3(10/71) and 3(1/7) using inscribed and circumscribed polygons. Zu Chongzhi (480 CE) pushed this to a 24,576-sided polygon and found the remarkably accurate fraction 355/113 ≈ 3.1415929.","visual":"📜"},{"title":"Mādhava's Infinite Series","body":"Āryabhaṭa (499 CE) gave π ≈ 3.1416, calling it 'asanna' — approaching, or approximate. Later, Mādhava of Sangamagrāma discovered the first exact formula for π, as an infinite series: π/4 = 1 − 1/3 + 1/5 − 1/7 + … This idea eventually gave birth to calculus.","visual":"♾️"},{"title":"π Is Irrational","body":"The digits of π go on forever with no repeating pattern, because π cannot be written as a fraction a/b of two integers — it is irrational (proved by Lambert in 1761). So we write π ≈ 22/7, but never π = 22/7.","visual":"🔢"}],"questions":[{"kind":"mcq","prompt":"The constant, fixed ratio of a circle's circumference to its diameter is called...","options":["π (pi)","φ (phi)","e","τ (tau)"],"answer":0,"explain":"This ratio, the same for circles of every size, is named π, from the Greek 'perimetros' for perimeter."},{"kind":"mcq","prompt":"Which mathematician described his value of π (3.1416) as 'asanna', meaning 'approaching' or 'approximate'?","options":["Āryabhaṭa","Brahmagupta","Baudhāyana","Ptolemy"],"answer":0,"explain":"Āryabhaṭa (499 CE) gave π ≈ 62832/20000 = 3.1416 and called it asanna, hinting that no single fraction could capture π exactly."},{"kind":"mcq","prompt":"Mādhava of Sangamagrāma's infinite series for π states that π/4 equals...","options":["1 − 1/3 + 1/5 − 1/7 + …","1 + 1/3 + 1/5 + 1/7 + …","1 − 1/2 + 1/3 − 1/4 + …","1/2 + 1/4 + 1/8 + 1/16 + …"],"answer":0,"explain":"Mādhava's series π/4 = 1 − 1/3 + 1/5 − 1/7 + … was the first exact formula for π and helped birth calculus."},{"kind":"mcq","prompt":"Which statement about π is TRUE?","options":["π is irrational — it cannot be written as a ratio of two integers","π is exactly equal to 22/7","π is a rational number with a repeating decimal pattern","π was proven irrational by Archimedes"],"answer":0,"explain":"π cannot be written as a fraction a/b of integers; this was proved by Lambert in 1761. 22/7 is only a close approximation."},{"kind":"mcq","prompt":"Which fraction, discovered by Zu Chongzhi, remained the most accurate rational approximation of π in the world for over 800 years?","options":["355/113","22/7","377/120","62832/20000"],"answer":0,"explain":"Zu Chongzhi's 'Miü' (Close Ratio) 355/113 ≈ 3.1415929 stayed unmatched by any simpler fraction for over 800 years."}]},{"id":"ms3","title":"Arcs, Circuits, and Staggers","icon":"🏟️","kind":"lesson","story":"Back at the athletics track: two straight stretches and two curved ends shaped like semicircles make up one lap. To calculate exactly how far each runner travels — and how much of a head start the outer lanes truly deserve — you need to turn circles and arcs into hard numbers.","teach":[{"title":"Circumference","body":"The circumference of a circle of diameter d is πd. Since diameter is twice the radius, we can also write it as C = 2πr, where r is the radius.","visual":"⭕"},{"title":"Semicircles and Quarter Circles","body":"A semicircle (half a circle, by reflection or a half-turn) has arc length 2πr ÷ 2 = πr. A quarter circle (by a quarter-turn) has arc length 2πr ÷ 4 = πr/2.","visual":"🌗"},{"title":"General Arc Length","body":"If an arc AB subtends an angle θ° at the centre O of a circle of radius r, the length of the arc is 2πr × θ°/360°.","visual":"📐"},{"title":"A 400 m Track","body":"A 400 m track has two straights of 84.39 m each, plus two semicircular ends that together form one full circle. Running 0.3 m from the inner border (radius 36.5 + 0.3 = 36.8 m), the circular part has circumference 2 × 3.1416 × 36.8 ≈ 231.22 m, so 168.78 + 231.22 = 400 m in total.","visual":"🏃"}],"questions":[{"kind":"numeric","prompt":"Using π ≈ 22/7, find the circumference (in cm) of a circle with radius 7 cm.","answer":44,"explain":"C = 2πr = 2 × 22/7 × 7 = 44 cm."},{"kind":"numeric","prompt":"Using π ≈ 22/7, find the length (in m) of an arc of a circle with radius 6.3 m that subtends an angle of 120° at the centre.","answer":13.2,"explain":"Circumference = 2 × 22/7 × 6.3 = 39.6 m; arc length = 39.6 × 120/360 = 13.2 m."},{"kind":"numeric","prompt":"Using π ≈ 3.14, find the length (in cm) of a semicircular arc of radius 10 cm.","answer":31.4,"explain":"A semicircular arc has length πr = 3.14 × 10 = 31.4 cm."},{"kind":"mcq","prompt":"If an arc subtends an angle θ° at the centre of a circle of radius r, its length is...","options":["2πr × θ°/360°","πr × θ°","2πr + θ°/360°","πr²  × θ°/360°"],"answer":0,"explain":"The arc is the fraction θ°/360° of the full circumference 2πr, giving length 2πr × θ°/360°."},{"kind":"numeric","prompt":"On a 400 m track, an athlete runs two straights of 84.39 m each, plus two semicircular ends of radius 36.8 m that together form a full circle of circumference 231.22 m (using π ≈ 3.1416). What is the total distance (in m) she runs in one circuit?","answer":400,"explain":"168.78 m (straights) + 231.22 m (curves) = 400 m — exactly one lap."}]},{"id":"ms4","title":"Rebuilding Rectangles","icon":"📏","kind":"lesson","story":"A farmer hands you a rough sketch of her land — rectangles, slanted parallelogram-shaped plots, and triangular corners — and wants to know how much seed she needs. There's no area formula painted on the ground, so you'll have to rebuild each odd shape out of rectangles, piece by piece.","teach":[{"title":"Area of a Rectangle","body":"The unit of area is a 1×1 square, with area 1 sq. unit. A rectangle with sides a units and b units has area ab sq. units; a square with side a has area a² sq. units, a special case with a = b.","visual":"🟩"},{"title":"Area of a Parallelogram","body":"A parallelogram can be cut and rearranged into a rectangle with the same base b and the same height h (the perpendicular distance between the parallel sides), without changing its area. So the area of a parallelogram is base × height = bh.","visual":"🔷"},{"title":"Area of a Triangle","body":"Two congruent copies of a triangle can be fitted together to make a parallelogram with the same base and height. Since that parallelogram has area bh, each triangle has half that area: area = ½ × base × height = ½bh.","visual":"🔺"},{"title":"The Median Theorem","body":"A median joins a vertex to the midpoint of the opposite side. Since the two halves of the opposite side are equal and the height from the vertex is the same for both, a median always divides a triangle into two triangles of equal area — even though they are usually not congruent to each other.","visual":"⚖️"}],"questions":[{"kind":"numeric","prompt":"Find the area (in sq. cm) of a rectangle with sides 15 cm and 8 cm.","answer":120,"explain":"Area of a rectangle = a × b = 15 × 8 = 120 sq. cm."},{"kind":"numeric","prompt":"Find the area (in sq. cm) of a parallelogram with base 12 cm and height 5 cm.","answer":60,"explain":"Area of a parallelogram = base × height = 12 × 5 = 60 sq. cm."},{"kind":"numeric","prompt":"Find the area (in sq. cm) of a triangle with base 10 cm and height 8 cm.","answer":40,"explain":"Area of a triangle = ½ × base × height = ½ × 10 × 8 = 40 sq. cm."},{"kind":"mcq","prompt":"A median of a triangle always divides it into two triangles that...","options":["have equal area, though they are usually not congruent to each other","are always congruent to each other","have areas in the ratio 2:1","have equal perimeter"],"answer":0,"explain":"Since both smaller triangles share the same height and equal base-halves, their areas are equal — even though their shapes usually differ."},{"kind":"mcq","prompt":"The formula 'area of parallelogram = base × height' works because...","options":["a parallelogram can be cut and rearranged into a rectangle with the same base and height, without changing its area","all parallelograms are actually rectangles","the diagonals of a parallelogram are always equal","a parallelogram has the same perimeter as its equivalent rectangle"],"answer":0,"explain":"Transforming the parallelogram into a same-base, same-height rectangle preserves area, and a rectangle's area is base × height."}]},{"id":"ms5","title":"Heron and the Four-Sided Field","icon":"🏺","kind":"lesson","story":"A surveyor gives you only the three side lengths of a triangular plot — no height, no angles marked anywhere. Two thousand years ago, Heron of Alexandria faced this exact puzzle and cracked it with a strange, beautiful formula. Centuries later, Brahmagupta pushed the same idea to four-sided fields.","teach":[{"title":"The Semi-Perimeter","body":"For a triangle with sides a, b, c, the semi-perimeter s is half the perimeter: s = ½(a + b + c).","visual":"➗"},{"title":"Heron's Formula","body":"The area of a triangle with sides a, b, c is √[s(s−a)(s−b)(s−c)], where s is the semi-perimeter. For the 3-4-5 triangle, s = 6, so area = √(6×3×2×1) = √36 = 6 sq. units — matching ½ × base × height.","visual":"📐"},{"title":"Circumcircle and Incircle Formulas","body":"Given any triangle ABC with sides a, b, c: its circumcircle (radius R) passes through all three vertices, and its incircle (radius r) touches all three sides. The area can also be written as abc/4R, or as r(a+b+c)/2.","visual":"⭕"},{"title":"Brahmagupta's Formula","body":"For a cyclic 4-gon (one whose vertices all lie on a circle) with sides a, b, c, d and semi-perimeter s = ½(a+b+c+d), the area is √[(s−a)(s−b)(s−c)(s−d)]. Since a triangle is a cyclic 4-gon with a fourth side of length 0, Brahmagupta's formula generalises Heron's formula.","visual":"🔷"}],"questions":[{"kind":"numeric","prompt":"Using Heron's formula, find the area (in sq. units) of a triangle with sides 3, 4, and 5 units.","answer":6,"explain":"s = ½(3+4+5) = 6; area = √(6×3×2×1) = √36 = 6 sq. units."},{"kind":"numeric","prompt":"Using Heron's formula, find the area (in sq. cm) of a triangle with sides 7 cm, 24 cm, and 25 cm.","answer":84,"explain":"s = ½(7+24+25) = 28; area = √(28×21×4×3) = √7056 = 84 sq. cm (also checkable as ½×7×24, since 7²+24²=25²)."},{"kind":"numeric","prompt":"Using Brahmagupta's formula, find the area (in sq. units) of a rectangle with sides 6 units and 9 units.","answer":54,"explain":"All rectangles are cyclic; Brahmagupta's formula reduces to √(ab·ab) = ab = 6 × 9 = 54 sq. units."},{"kind":"mcq","prompt":"Brahmagupta's formula for area using only the side lengths applies to which shape?","options":["A cyclic quadrilateral (4-gon)","Any quadrilateral, cyclic or not","Only squares and rectangles","Any triangle"],"answer":0,"explain":"Brahmagupta's formula requires the 4-gon to be cyclic — its vertices must all lie on one circle — since side lengths alone don't fix the area of a general 4-gon."},{"kind":"mcq","prompt":"Heron's formula can be seen as a special case of Brahmagupta's formula when...","options":["one side of the cyclic 4-gon shrinks to zero length, turning it into a triangle","all four sides of the 4-gon are equal","the 4-gon becomes a square","the semi-perimeter equals zero"],"answer":0,"explain":"Setting d = 0 in Brahmagupta's formula makes two vertices coincide, turning the cyclic 4-gon into a triangle, and the formula reduces exactly to Heron's formula."}]},{"id":"ms6","title":"The Shape of a Circle's Space","icon":"🌀","kind":"lesson","story":"Grain silos, circular gardens, watchtowers — ancient builders needed to know how much space a circle truly holds, not just the length of its edge. Babylonians guessed, Egyptians guessed better, and finally Archimedes proved the exact answer using nothing but triangles sliced impossibly thin.","teach":[{"title":"A Ratio Fixed by Shape","body":"For any square, P²:A = 16:1. For any equilateral triangle, P²:A = 36:√3. For a fixed shape, the ratio (perimeter)²:area never changes with size — only with the shape itself. This suggested that for circles too, C²:A must be some fixed constant.","visual":"📏"},{"title":"From Guesses to Proof","body":"Babylonians estimated C²:A ≈ 12:1. Egyptians and the Baudhāyana Śhulbasūtra used a more accurate approximation equivalent to A ≈ (256/81)r². Around 250 BCE, Archimedes finally proved the constant is exactly π, so A = πr².","visual":"🏺"},{"title":"Nīlakaṇṭha's Visual Proof","body":"Nīlakaṇṭha Somayājī (c. 1500) showed that slicing a circle into thin sectors and rearranging them gives a shape that looks like a parallelogram, with base = half the circumference = πr and height = radius r. So area of circle = base × height = πr × r = πr².","visual":"🧩"},{"title":"Area of a Sector","body":"A sector subtending angle θ° at the centre has area πr² × θ°/360°. A semicircular disc (θ = 180°) has area ½πr²; a quarter circular disc (θ = 90°) has area ¼πr².","visual":"🍕"}],"questions":[{"kind":"numeric","prompt":"Using π ≈ 22/7, find the area (in sq. cm) of a circle with radius 7 cm.","answer":154,"explain":"Area = πr² = 22/7 × 49 = 154 sq. cm."},{"kind":"numeric","prompt":"Using π ≈ 22/7, find the area (in sq. cm) of a sector of radius 21 cm with a sector angle of 60°.","answer":231,"explain":"Area = πr² × θ°/360° = 22/7 × 441 × 60/360 = 1386 × 1/6 = 231 sq. cm."},{"kind":"numeric","prompt":"Using π ≈ 22/7, find the area (in sq. cm) of a semicircular disc of radius 14 cm.","answer":308,"explain":"Full circle area = 22/7 × 196 = 616 sq. cm; semicircular disc = 616 ÷ 2 = 308 sq. cm."},{"kind":"mcq","prompt":"A sector of a circle that subtends an angle θ° at the centre has area...","options":["πr² × θ°/360°","2πr × θ°/360°","½πr²","πr² + θ°"],"answer":0,"explain":"A sector is the fraction θ°/360° of the whole circle's area πr², giving area = πr² × θ°/360°."},{"kind":"numeric","prompt":"Using π ≈ 22/7, a circle has circumference 44 cm. Find the area (in sq. cm) of a quadrant (quarter) of this circle.","answer":38.5,"explain":"From 2πr = 44, radius r = 7 cm; quadrant area = ¼πr² = ¼ × 22/7 × 49 = ¼ × 154 = 38.5 sq. cm."}]},{"id":"ms-boss","title":"The Circle Sentinel","icon":"👑","kind":"boss","story":"Every measurer who ever faced a circle stands before you at once — Mesopotamian surveyors, Archimedes with his polygons, Brahmagupta with his four-sided fields, and Mādhava with his infinite sum. Prove you've mastered perimeter and area, from straight edges to endless curves, or be sent back to the starting stagger.","boss":{"name":"The Circle Sentinel","taunt":"Bring me your best fraction — I am the ratio that no fraction can ever catch."},"questions":[{"kind":"numeric","prompt":"Find the perimeter (in m) of a rectangle with length 20 m and width 12 m.","answer":64,"explain":"Perimeter = 2(a + b) = 2(20 + 12) = 64 m."},{"kind":"numeric","prompt":"Using π ≈ 22/7, find the circumference (in cm) of a circle with radius 14 cm.","answer":88,"explain":"C = 2πr = 2 × 22/7 × 14 = 88 cm."},{"kind":"numeric","prompt":"Find the area (in sq. cm) of a triangle with base 16 cm and height 5 cm.","answer":40,"explain":"Area = ½ × base × height = ½ × 16 × 5 = 40 sq. cm."},{"kind":"numeric","prompt":"Using Heron's formula, find the area (in sq. units) of an isosceles triangle with sides 5, 5, and 6 units.","answer":12,"explain":"s = ½(5+5+6) = 8; area = √(8×3×3×2) = √144 = 12 sq. units."},{"kind":"numeric","prompt":"Using π ≈ 3.14, find the area (in sq. cm) of a circle with radius 10 cm.","answer":314,"explain":"Area = πr² = 3.14 × 100 = 314 sq. cm."},{"kind":"mcq","prompt":"Who first proved that the ratio C²:A for a circle is exactly π, giving the formula A = πr²?","options":["Archimedes","Āryabhaṭa","Brahmagupta","Mādhava"],"answer":0,"explain":"Around 250 BCE, Archimedes proved that the constant relating a circle's squared circumference to its area is exactly π."},{"kind":"mcq","prompt":"Brahmagupta's formula, using only the four side lengths a, b, c, d, computes the area of a...","options":["cyclic quadrilateral","regular hexagon","right-angled triangle","parallelogram"],"answer":0,"explain":"Brahmagupta's formula √[(s-a)(s-b)(s-c)(s-d)] gives the area of a cyclic 4-gon, one whose vertices all lie on a single circle."},{"kind":"numeric","prompt":"Using π ≈ 3.14, find the area (in sq. cm) of a sector of radius 6 cm with a sector angle of 90°.","answer":28.26,"explain":"Area = πr² × θ°/360° = 3.14 × 36 × 90/360 = 3.14 × 9 = 28.26 sq. cm."}]}]},{"id":"probability9","index":6,"name":"The Mathematics of Maybe","subtitle":"Ganita Manjari Chapter 7 — Probability","emoji":"🎲","palette":{"from":"#818cf8","to":"#312e81"},"lessons":[{"id":"pr1","title":"Randomness & the Probability Scale","icon":"🌦️","kind":"lesson","story":"Your friend asks if it will rain today, and whether your school will win tomorrow's hockey match. You don't know for sure — but you're not totally clueless either. Welcome to the mathematics of maybe.","teach":[{"title":"Probability Measures Likelihood","body":"Probability is a type of measurement, just like length or volume — except instead of measuring physical quantities, it measures how likely an event is to happen. It helps us express how confident we are that something will occur.","visual":"📏"},{"title":"What is Randomness?","body":"A random experiment (like tossing a coin or rolling a die) can be repeated, and every time you do it the result might be different — you cannot know the outcome in advance, even though you know all the possible outcomes.","visual":"🎲"},{"title":"The Probability Scale","body":"Probability is measured on a scale from 0 to 1. A probability of 0 means impossible, 1 means certain, and 0.5 means an even chance. Most real events fall strictly between 0 and 1.","visual":"📊"}],"questions":[{"kind":"mcq","prompt":"On the probability scale, what does a probability of 0 mean?","options":["The event is impossible","The event is certain","The event has an even chance","The event has already happened"],"answer":0,"explain":"A probability of 0 sits at the impossible end of the 0-to-1 scale."},{"kind":"mcq","prompt":"What is the probability of rolling a number greater than 6 on a standard six-sided die?","options":["0 (impossible)","0.5 (even chance)","1 (certain)","0.167 (less likely)"],"answer":0,"explain":"A standard die only has faces numbered 1 to 6, so rolling above 6 can never happen."},{"kind":"mcq","prompt":"Which of these best describes a random experiment?","options":["It can be repeated, and each time the result may differ and cannot be known in advance","It always gives exactly the same result every time it is performed","It has only one possible outcome","It can never be repeated under the same conditions"],"answer":0,"explain":"Randomness means the outcome is unpredictable each time, even though you know what outcomes are possible."},{"kind":"numeric","prompt":"On the probability scale (0 = impossible to 1 = certain), what number represents an event that is certain to happen?","answer":1,"explain":"A probability of 1 means the event is certain."},{"kind":"mcq","prompt":"Which event has an even chance (probability 0.5) of happening?","options":["Flipping a fair coin and getting heads","Rolling a number greater than 6 on a die","Picking a red sweet from a bag containing only red sweets","Rolling a 3 on a standard six-sided die"],"answer":0,"explain":"Heads and tails are equally likely, so a fair coin toss is an even-chance event."}]},{"id":"pr2","title":"Experimental Probability","icon":"📈","kind":"lesson","story":"Instead of just reasoning about a coin or die, what if you actually tossed it — again and again — and counted what really happened? That's how you measure probability from evidence.","teach":[{"title":"Sample Space & Outcomes","body":"In an experiment, the result is called an outcome, and the set of all possible outcomes is the sample space. Tossing a coin gives sample space {H, T}; rolling a die gives sample space {1, 2, 3, 4, 5, 6}.","visual":"🎯"},{"title":"Experimental Probability Formula","body":"Experimental Probability = Number of times the event occurred ÷ Total number of trials. It is based on real collected data (an experiment or past observations), so it's also called relative frequency.","visual":"📋"},{"title":"Worked Example","body":"Suppose you roll a die 50 times and it lands on 4 exactly 8 times. The experimental probability of rolling a 4 is 8/50 = 0.16, i.e. the relative frequency of rolling a 4 is 0.16.","visual":"🎲"}],"questions":[{"kind":"mcq","prompt":"How is experimental probability calculated?","options":["Number of times the event occurred ÷ total number of trials","Number of favourable outcomes ÷ number of possible outcomes","Total number of trials ÷ number of times the event occurred","Number of outcomes in the sample space ÷ 2"],"answer":0,"explain":"Experimental probability (relative frequency) is based on actually observed data from trials."},{"kind":"numeric","prompt":"You roll a die 50 times and it lands on 4 exactly 8 times. What is the experimental probability of rolling a 4?","answer":0.16,"explain":"8 ÷ 50 = 0.16."},{"kind":"mcq","prompt":"What is the sample space for tossing a single fair coin?","options":["{H, T}","{H, H, T, T}","{1, 2}","{Heads only}"],"answer":0,"explain":"A coin toss has exactly two possible outcomes: Heads or Tails."},{"kind":"mcq","prompt":"A teacher samples 30 sweets from a large bag: 10 red, 8 green, 7 yellow, 5 blue. What is the experimental probability that a randomly picked sweet from this sample is green?","options":["≈0.27","≈0.33","≈0.23","≈0.17"],"answer":0,"explain":"8 green sweets out of 30 total gives 8/30 ≈ 0.267."},{"kind":"numeric","prompt":"What is the sample size n(S) for the experiment of rolling a standard six-sided die?","answer":6,"explain":"The sample space {1, 2, 3, 4, 5, 6} has 6 elements."}]},{"id":"pr3","title":"Theoretical Probability & Statistical Data","icon":"🧮","kind":"lesson","story":"No die in hand, no experiment to run — can you still work out the odds? If every outcome is equally likely, you can calculate probability with pure reasoning, or estimate it from a survey.","teach":[{"title":"Theoretical Probability Formula","body":"Theoretical Probability P(Event) = Number of favourable outcomes ÷ Number of possible outcomes, assuming all outcomes are equally likely. No experiment or data is required — it's pure reasoning about a fair situation.","visual":"🧮"},{"title":"Worked Examples","body":"Rolling a fair die: P(getting a 4) = 1/6 ≈ 0.167. Picking a letter at random from the word PROBABILITY (11 letters, 2 of which are B): P(picking B) = 2/11 ≈ 0.182.","visual":"🔤"},{"title":"Statistical Probability from Data","body":"Statistical probability is estimated from collected survey or population data. If 20 of 50 surveyed students like mango best, P(mango) = 20/50 = 0.4. This estimate can then be used to predict results for a larger population — collecting evidence from a sample is called sampling.","visual":"🍊"}],"questions":[{"kind":"mcq","prompt":"How is theoretical probability calculated?","options":["Number of favourable outcomes ÷ number of possible outcomes","Number of times an event occurred ÷ total number of trials","Number of possible outcomes ÷ number of favourable outcomes","Total outcomes minus favourable outcomes"],"answer":0,"explain":"Theoretical probability assumes all outcomes are equally likely and compares favourable outcomes to all possible outcomes."},{"kind":"numeric","prompt":"What is the theoretical probability of rolling a 4 on a standard six-sided die? (round to 3 decimal places)","answer":0.167,"explain":"1 favourable outcome ÷ 6 possible outcomes = 0.1666... ≈ 0.167."},{"kind":"numeric","prompt":"A letter is picked at random from the word PROBABILITY (11 letters, including 2 B's). What is the probability of picking the letter B? (round to 3 decimal places)","answer":0.182,"explain":"2 favourable outcomes ÷ 11 possible outcomes = 0.1818... ≈ 0.182."},{"kind":"mcq","prompt":"In a survey of 50 students, 20 said mango is their favourite fruit. What is the estimated probability that a randomly chosen student from this class prefers mango?","options":["0.4","0.2","0.5","0.6"],"answer":0,"explain":"20 ÷ 50 = 0.4, so there is a 40% chance."},{"kind":"numeric","prompt":"Using that same survey (20 of 50 students prefer mango), about how many students would you expect to prefer mango out of a whole school of 1500 students?","answer":600,"explain":"0.4 × 1500 = 600 students, based on the sample proportion."}]},{"id":"pr4","title":"Law of Large Numbers & Gambler's Fallacy","icon":"🪙","kind":"lesson","story":"A fair coin lands on heads six times in a row during a game. Surely tails is 'due' next... right? A classic trap is waiting for you — and understanding it is key to thinking clearly about chance.","teach":[{"title":"Law of Large Numbers","body":"Even in a perfectly fair situation, experimental probability can differ from theoretical probability, especially with few trials. As the number of trials increases, experimental probability tends to get closer to theoretical probability — this is the Law of Large Numbers.","visual":"📉"},{"title":"Gambler's Fallacy","body":"Many people think that after a random outcome happens several times in a row, the opposite is 'due' to happen next. But a coin (or die) has no memory — each toss or roll is independent, so the probability stays exactly the same every time. This mistaken belief is called the Gambler's Fallacy.","visual":"🪙"},{"title":"Fair and Unbiased","body":"A 'fair' or 'unbiased' coin or die is symmetrical, so there is no reason for it to land on one side more often than another. A 'random toss' means it is allowed to fall freely, without any bias or interference.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"A fair coin has just landed on heads 6 times in a row. What is the probability it lands on tails on the next flip?","options":["0.5, because the coin has no memory of past flips","Greater than 0.5, since tails is 'due' to appear","0, because heads always wins after a streak","1, because tails must come next"],"answer":0,"explain":"Each coin flip is an independent event, so the probability of tails is always 0.5 regardless of past flips."},{"kind":"mcq","prompt":"What is the Gambler's Fallacy?","options":["The mistaken belief that past random outcomes affect the probability of future independent events","The correct rule that probability changes after each trial","A formula for calculating theoretical probability","The tendency for dice to become biased with repeated use"],"answer":0,"explain":"The Gambler's Fallacy tricks people into believing randomness has a memory or pattern, when it does not."},{"kind":"mcq","prompt":"According to the Law of Large Numbers, what happens as the number of trials in a random experiment increases?","options":["Experimental probability tends to get closer to theoretical probability","Experimental probability becomes completely unpredictable","Theoretical probability changes to match the collected data","The sample space grows larger with each trial"],"answer":0,"explain":"With more trials, observed relative frequency converges toward the theoretical probability."},{"kind":"numeric","prompt":"While playing Snakes and Ladders with a fair die, you have just rolled three 6's in a row. What is the theoretical probability of rolling a 6 on the next roll? (round to 3 decimal places)","answer":0.167,"explain":"Each roll is independent, so the probability of rolling a 6 is still 1/6 ≈ 0.167, unaffected by the previous rolls."}]},{"id":"pr5","title":"Sample Spaces, Events & Tree Diagrams","icon":"🌳","kind":"lesson","story":"Toss two coins at once and there are more possibilities than you might think. To keep track of every path chance could take, mathematicians draw a tree — and pick out just the branches they care about.","teach":[{"title":"Sample Space (S)","body":"The sample space S is the list of every possible outcome of a random experiment — each outcome listed once. The number of elements in it is the sample size, n(S). Tossing two coins gives S = {HH, HT, TH, TT}, so n(S) = 4.","visual":"📋"},{"title":"Events","body":"An event is any single outcome or combination of outcomes from the sample space — it is a subset of the sample space. For example, when rolling a die, the event 'the number rolled is greater than 4' is E = {5, 6}.","visual":"🎯"},{"title":"Tree Diagrams","body":"A tree diagram visually lists all outcomes of a multi-step experiment, like tossing a coin twice. Each branch represents a possible outcome; following all paths from start to end gives the full sample space, and probabilities can be marked on each branch.","visual":"🌳"}],"questions":[{"kind":"mcq","prompt":"What is a sample space?","options":["The set of all possible outcomes of a random experiment","One single outcome of an experiment","A subset of only the favourable outcomes","The probability of a particular event"],"answer":0,"explain":"The sample space, denoted S, must include every possible outcome exactly once."},{"kind":"numeric","prompt":"Two fair coins are tossed simultaneously. What is the sample size n(S)?","answer":4,"explain":"The sample space is S = {HH, HT, TH, TT}, which has 4 elements."},{"kind":"mcq","prompt":"When rolling a standard six-sided die, what is the event 'the number rolled is greater than 4'?","options":["{5, 6}","{1, 2, 3, 4}","{4, 5, 6}","{6}"],"answer":0,"explain":"Only 5 and 6 are greater than 4 on a standard die."},{"kind":"numeric","prompt":"Using a tree diagram for tossing a fair coin twice, what is the theoretical probability of getting heads both times (HH)?","answer":0.25,"explain":"Out of 4 equally likely outcomes {HH, HT, TH, TT}, only 1 is HH, so P(HH) = 1/4 = 0.25."},{"kind":"mcq","prompt":"An event is best described as...","options":["A subset of outcomes chosen from the sample space","The total number of trials performed in an experiment","Always exactly half of the sample space","A random experiment itself"],"answer":0,"explain":"An event is any single outcome or group of outcomes picked from all the outcomes that could occur."}]},{"id":"pr-boss","title":"Boss: The Probability Phantom","icon":"👑","kind":"boss","boss":{"name":"The Probability Phantom","taunt":"You think you can measure Maybe? Prove it — or stay uncertain forever!"},"story":"The Probability Phantom lurks between certainty and impossibility, feeding on confused guesses and gambler's fallacies. Only a mind that has mastered randomness, sample spaces, and the probability scale can banish it for good.","teach":[{"title":"Chapter Recap","body":"Probability measures likelihood on a scale from 0 (impossible) to 1 (certain): 0 ≤ P(E) ≤ 1. Experimental probability comes from real trials (occurrences ÷ trials); theoretical probability comes from reasoning about equally likely outcomes (favourable ÷ possible).","visual":"🧠"},{"title":"Sample Spaces, Events & Trees","body":"A sample space S lists every possible outcome exactly once; an event is a subset of that sample space. Tree diagrams help list and visualise all outcomes of multi-step experiments, like tossing a coin twice.","visual":"🌳"}],"questions":[{"kind":"mcq","prompt":"The probability of any event E always satisfies:","options":["0 ≤ P(E) ≤ 1","P(E) ≥ 1","-1 ≤ P(E) ≤ 1","P(E) is always exactly 0.5"],"answer":0,"explain":"Probability is always measured on a scale from 0 (impossible) to 1 (certain)."},{"kind":"numeric","prompt":"A bag contains 3 red balls, 2 blue balls, and 1 green ball. One ball is picked at random. What is the probability that it is NOT red?","answer":0.5,"explain":"3 non-red balls (2 blue + 1 green) out of 6 total gives 3/6 = 0.5."},{"kind":"mcq","prompt":"Which of these is an example of theoretical probability rather than experimental probability?","options":["Reasoning that P(rolling a 4 on a fair die) = 1/6 without ever rolling it","Rolling a die 50 times and counting how often 4 appears","Recording the results of 20 actual coin flips","Surveying 50 students about their favourite fruit"],"answer":0,"explain":"Theoretical probability is calculated by reasoning about equally likely outcomes, with no experiment or data needed."},{"kind":"numeric","prompt":"Ten identical cards numbered 1 to 10 are placed in a box. One card is drawn at random. What is the probability of drawing a card with an even number?","answer":0.5,"explain":"5 even numbers (2, 4, 6, 8, 10) out of 10 cards gives 5/10 = 0.5."},{"kind":"mcq","prompt":"A coin has landed on heads 4 times in a row. Believing tails is now 'due' to happen is an example of:","options":["Gambler's Fallacy","The Law of Large Numbers","Theoretical probability","A biased sample space"],"answer":0,"explain":"Each coin flip is independent — the coin has no memory of previous flips, so believing tails is 'due' is the Gambler's Fallacy."},{"kind":"numeric","prompt":"A die is rolled once. What is the probability of getting a number greater than 4? (round to 3 decimal places)","answer":0.333,"explain":"The event {5, 6} has 2 favourable outcomes out of 6 possible, so 2/6 ≈ 0.333."}]}]},{"id":"sequences9","index":7,"name":"Predicting What Comes Next","subtitle":"Ganita Manjari Chapter 8 — Sequences and Progressions","emoji":"🔁","palette":{"from":"#2dd4bf","to":"#134e4a"},"lessons":[{"id":"sq1","title":"Reading the Pattern","icon":"🔍","kind":"lesson","story":"Deep in the Ruins of Ganita, you find ancient tile mosaics — some growing as triangles, some as squares. To unlock the vault door, you must learn to read these ordered trails of numbers, called sequences, before you can predict what tile comes next.","teach":[{"title":"Sequences and Terms","body":"A sequence is an ordered list of numbers where each number is called a term. Sequences can be finite (like 6, 12, 24, 48, 96) or infinite (like the natural numbers 1, 2, 3, 4, …). In the square number sequence 1, 4, 9, 16, 25, 36, …, 1 is the first term and 25 is the fifth term.","visual":"🔢"},{"title":"Triangular Numbers","body":"The triangular numbers 1, 3, 6, 10, 15, 21, … grow with differences 2, 3, 4, 5, 6 between consecutive terms. Each term is the sum of the natural numbers up to that point: 6 = 1+2+3, 10 = 1+2+3+4, and the fifth triangular number 15 = 1+2+3+4+5.","visual":"🔺"},{"title":"Square Numbers","body":"The square numbers 1, 4, 9, 16, 25, 36, … have differences 3, 5, 7, 9, 11 between consecutive terms. Each term is the sum of the odd numbers up to that point: 9 = 1+3+5, 16 = 1+3+5+7.","visual":"◻️"},{"title":"Naming Terms with tn","body":"We write t1, t2, t3, … for the first, second, third terms of a sequence — the subscript matches the position. For the odd numbers, t1 = 1, t2 = 3, t3 = 5, t4 = 7, so t4 = 7 tells us the term in the 4th position is 7.","visual":"🔤"}],"questions":[{"kind":"mcq","prompt":"Which of these is a FINITE sequence?","options":["6, 12, 24, 48, 96","1, 2, 3, 4, 5, 6, …","1, 3, 5, 7, 9, 11, …","1, 4, 9, 16, 25, 36, …"],"answer":0,"explain":"It has exactly five terms and stops, while the others continue forever, shown by the dots."},{"kind":"numeric","prompt":"What is the 6th triangular number?","answer":21,"explain":"1+2+3+4+5+6 = 21, matching the sequence 1, 3, 6, 10, 15, 21."},{"kind":"numeric","prompt":"The square number sequence is 1, 4, 9, 16, 25, 36, …. What is the difference between its 6th and 5th terms?","answer":11,"explain":"36 - 25 = 11, following the pattern of differences 3, 5, 7, 9, 11."},{"kind":"mcq","prompt":"In the sequence of odd numbers where t1 = 1, t2 = 3, t3 = 5, t4 = 7, what is t5?","options":["9","11","8","13"],"answer":0,"explain":"The odd numbers continue 1, 3, 5, 7, 9, … so t5 = 9."},{"kind":"numeric","prompt":"The 5th triangular number is 15, since 15 = 1+2+3+4+5. What is the 7th triangular number?","answer":28,"explain":"1+2+3+4+5+6+7 = 28."}]},{"id":"sq2","title":"The Explicit Dial","icon":"🧮","kind":"lesson","story":"The vault reveals a control panel with a single dial numbered 'n'. Turn it to any position and an explicit formula spits out the exact term at that position — no need to count from the start. Master the dial before the corridor beyond seals shut.","teach":[{"title":"What Is an Explicit Formula?","body":"An explicit formula uses a term's position number, n, to calculate its value directly — no need to know any other terms. For un = 2n − 1, substituting n = 1, 2, 3 gives u1 = 1, u2 = 3, u3 = 5, the sequence of odd numbers.","visual":"🎯"},{"title":"Jumping Straight to Any Term","body":"With an explicit formula we can find the 20th, 53rd or 300th term directly just by substituting n, with no need to compute every term before it. For tn = 3n − 7, the 12th term is t12 = 3(12) − 7 = 29.","visual":"🚀"},{"title":"Finding a Term's Position","body":"An explicit formula also lets us check whether a number belongs to a sequence, by solving for n. For the odd numbers un = 2n − 1, solving 2n − 1 = 137 gives n = 69, so 137 is the 69th term.","visual":"🔎"},{"title":"When n Isn't a Natural Number","body":"If solving the equation gives a value of n that is not a natural number, the number is NOT a term of the sequence. For sn = 5n − 2, solving 5n − 2 = 471 gives n = 94.6, so 471 is not a term — only whole-number positions count.","visual":"🚫"}],"questions":[{"kind":"numeric","prompt":"Using un = 2n − 1, find the 53rd term of the odd number sequence.","answer":105,"explain":"u53 = 2(53) − 1 = 105."},{"kind":"numeric","prompt":"For tn = 3n − 7, find the 12th term.","answer":29,"explain":"t12 = 3(12) − 7 = 36 − 7 = 29."},{"kind":"numeric","prompt":"Which term of the sequence tn = 3n − 7 equals 332?","answer":113,"explain":"3n − 7 = 332 gives 3n = 339, so n = 113."},{"kind":"numeric","prompt":"For sn = 5n − 2, find the 100th term.","answer":498,"explain":"s100 = 5(100) − 2 = 498."},{"kind":"numeric","prompt":"Is 557 a term of tn = 3n − 7? If so, which term is it?","answer":188,"explain":"3n − 7 = 557 gives 3n = 564, so n = 188, a natural number — so yes, it is the 188th term."}]},{"id":"sq3","title":"The Recursive Staircase","icon":"🔄","kind":"lesson","story":"Beyond the dial room lies a spiral staircase where each step is built from the ones before it. This is the realm of recursive rules — including the legendary sequence discovered by the poet-mathematician Virahānka over a thousand years before it reached Europe.","teach":[{"title":"Recursive Rules","body":"A recursive formula gives a term's value using the values of previous terms, instead of using n directly. For t1 = 1, tn = tn−1 + 3 (n ≥ 2), each term is 3 more than the one before it, generating 1, 4, 7, 10, 13, …","visual":"🔗"},{"title":"Building Up Term by Term","body":"For u1 = 1, un = 2un−1 + 3 (n ≥ 2): u2 = 2(1)+3 = 5, u3 = 2(5)+3 = 13, u4 = 2(13)+3 = 29. You must know each earlier term to find the next one.","visual":"🧱"},{"title":"Two Terms Back: Virahānka–Fibonacci","body":"A recursive rule can use more than one previous term. The Virahānka–Fibonacci sequence has V1 = 1, V2 = 2, and Vn = Vn−1 + Vn−2 for n ≥ 3, giving 1, 2, 3, 5, 8, 13, 21, 34, … where each term is the sum of the two before it.","visual":"🌀"},{"title":"A 1,300-Year-Old Discovery","body":"This sequence was first written down explicitly by Virahānka in his 7th-century CE work on Prakrit poetry meter, later studied by Gopāla and Hemachandra, and studied again by the Italian mathematician Fibonacci around 1200 CE.","visual":"📜"}],"questions":[{"kind":"numeric","prompt":"For u1 = 1, un = 2un−1 + 3, find u4.","answer":29,"explain":"u2 = 5, u3 = 13, u4 = 2(13)+3 = 29."},{"kind":"numeric","prompt":"The Virahānka–Fibonacci sequence is 1, 2, 3, 5, 8, 13, 21, 34, … (V1 to V8). What is V9?","answer":55,"explain":"V9 = V8 + V7 = 34 + 21 = 55."},{"kind":"mcq","prompt":"To find the next term using a recursive rule, what must you already know?","options":["The values of the earlier terms","Only the position number n","Nothing else is needed","The final term of the sequence"],"answer":0,"explain":"A recursive rule defines each term in terms of the term(s) before it, so the earlier terms must be known."},{"kind":"numeric","prompt":"For s1 = 3, sn = sn−1(sn−1 − 1), find s4.","answer":870,"explain":"s2 = 3×2 = 6, s3 = 6×5 = 30, s4 = 30×29 = 870."},{"kind":"mcq","prompt":"Who first wrote down the Virahānka–Fibonacci sequence explicitly, in the context of Prakrit poetry meter in the 7th century CE?","options":["Virahānka","Fibonacci","Āryabhaṭa","Hemachandra"],"answer":0,"explain":"Virahānka studied it in his work Vṛttajātisamuchaya, centuries before Fibonacci."}]},{"id":"sq4","title":"The Constant-Difference Road","icon":"📏","kind":"lesson","story":"A taxi waits at the city gates, its meter ticking a fixed booking fee plus a steady rate per kilometre. Its fare sequence marches forward with perfect regularity — welcome to the land of Arithmetic Progressions, where every step adds the same constant difference.","teach":[{"title":"What Is an Arithmetic Progression?","body":"An arithmetic progression (AP) is a sequence where the difference between consecutive terms is constant — this constant is called the common difference, d. The general form is a, a+d, a+2d, a+3d, …, where a is the first term.","visual":"📏"},{"title":"The nth Term of an AP","body":"The nth term of an AP is tn = a + (n − 1)d. For the sequence 1, 5, 9, 13, 17, … (from a growing pattern of squares), a = 1 and d = 4, so tn = 1 + (n−1)×4 = 4n − 3.","visual":"🧮"},{"title":"Recursive Rule for an AP","body":"An AP can also be described recursively as t1 = a, tn = tn−1 + d for n ≥ 2. For the AP 1, 5, 9, 13, 17, …, this means t1 = 1, tn = tn−1 + 4.","visual":"🔁"},{"title":"APs in Real Life: Taxi Fares","body":"A taxi charges a fixed ₹200 booking fee plus ₹40 per km. The fare sequence 240, 280, 320, … is an AP with a = 240 and d = 40, so the nth term (fare after n km) is 200 + 40n.","visual":"🚕"}],"questions":[{"kind":"numeric","prompt":"Find the 10th term of the AP 3, 8, 13, 18, …","answer":48,"explain":"a = 3, d = 5, so t10 = 3 + 9(5) = 48."},{"kind":"numeric","prompt":"Find the 26th term of the AP 3, 8, 13, 18, …","answer":128,"explain":"t26 = 3 + 25(5) = 128."},{"kind":"mcq","prompt":"Is 0 a term of the AP 21, 18, 15, …?","options":["Yes, it is the 8th term","No, because n comes out negative","Yes, it is the 7th term","No, this AP has no common difference"],"answer":0,"explain":"a = 21, d = -3; solving 21 + (n-1)(-3) = 0 gives n = 8, a natural number, so 0 is the 8th term."},{"kind":"numeric","prompt":"A taxi charges ₹200 plus ₹40/km, giving the fare sequence 240, 280, 320, …. What is the total fare after travelling 10 km?","answer":600,"explain":"Fare = 200 + 40n = 200 + 40(10) = 600."},{"kind":"numeric","prompt":"An AP has 50 terms; its 3rd term is 12 and its 50th (last) term is 106. Find the 29th term.","answer":64,"explain":"Solving a+2d=12 and a+49d=106 gives d=2, a=8, so t29 = 8 + 28(2) = 64."}]},{"id":"sq5","title":"Gauss's Shortcut","icon":"➕","kind":"lesson","story":"A monk hands you a scroll bearing 1+2+3+…+100 — add it term by term and you will be here till nightfall. Legend speaks of an ancient trick, later immortalized in Āryabhaṭa's Āryabhaṭīya, that cracks it in seconds by pairing the numbers cleverly.","teach":[{"title":"The Reverse-and-Add Trick","body":"To find S = 1+2+…+n, write it forwards and backwards and add: S = 1+2+…+n and S = n+(n−1)+…+1. Each pair adds to n+1, added n times, so 2S = n(n+1), giving Sn = n(n+1)/2.","visual":"➕"},{"title":"A Picture of the Sum","body":"Doubling the dots representing 1+2+3+4+5+6 forms a 7×6 rectangular array, showing 2×(1+2+3+4+5+6) = 7×6. This same reasoning gives 2×(1+2+…+n) = n×(n+1) for any n.","visual":"🔲"},{"title":"An Ancient Result","body":"The earliest known written record of this formula appears in Āryabhaṭa's Āryabhaṭīya (Chapter 2, Verse 19), which describes the sum as the average of the first and last term multiplied by the number of terms.","visual":"📖"},{"title":"Summing a Range of Numbers","body":"The formula also finds sums like 25+26+…+58 by subtracting: S58 − S24 = (58×59/2) − (24×25/2) = 1711 − 300 = 1411. Also, the nth triangular number equals Sn: tn = n(n+1)/2.","visual":"➗"}],"questions":[{"kind":"numeric","prompt":"Find the sum of the first 10 natural numbers.","answer":55,"explain":"S10 = 10(11)/2 = 55."},{"kind":"numeric","prompt":"Find S20, the sum of the first 20 natural numbers.","answer":210,"explain":"S20 = 20(21)/2 = 210."},{"kind":"mcq","prompt":"The earliest known written record of the sum-of-natural-numbers formula appears in which ancient Indian text?","options":["Āryabhaṭa's Āryabhaṭīya","Virahānka's Vṛttajātisamuchaya","Ganita Manjari","the Sulba Sutras"],"answer":0,"explain":"It appears in Chapter 2, Verse 19 of Āryabhaṭa's Āryabhaṭīya."},{"kind":"numeric","prompt":"Find the sum 25 + 26 + 27 + … + 58 using Sn formulas.","answer":1411,"explain":"S58 - S24 = 1711 - 300 = 1411."},{"kind":"numeric","prompt":"A child arranges marbles in rows: 1 in the first row, 2 in the second, …, up to 25 rows. How many marbles in total?","answer":325,"explain":"Total = S25 = 25(26)/2 = 325."}]},{"id":"sq6","title":"The Sierpiński Ruins","icon":"🔺","kind":"lesson","story":"You step into the Sierpiński ruins, where every triangle splinters into three smaller ones at each stage — multiplying without end, yet the shaded area shrinks toward nothing. This is the domain of Geometric Progressions, ruled by a constant ratio.","teach":[{"title":"What Is a Geometric Progression?","body":"A geometric progression (GP) is a sequence where each term is obtained by multiplying the previous term by a fixed common ratio, r. The general form is a, ar, ar², ar³, …, and the nth term is tn = ar^(n−1).","visual":"📐"},{"title":"GP in a Growing Pattern","body":"The number of green squares in a growing pattern is 3, 6, 12, 24, 48, …, doubling each stage. Here a = 3 and r = 2, so tn = 3 × 2^(n−1). The recursive rule is t1 = 3, tn = 2×tn−1.","visual":"🟩"},{"title":"The Sierpiński Triangle","body":"In the Sierpiński triangle fractal, each black triangle splits into 3 smaller ones at every stage, giving 1, 3, 9, 27, 81, 243, … black triangles — a GP with tn = 3^n. Yet the shaded area sn = (3/4)^n keeps shrinking toward zero even as the triangle count explodes.","visual":"🔻"},{"title":"GPs Don't Plot as Straight Lines","body":"Unlike an AP, plotting the terms of a GP against their position numbers does NOT give a straight line — the points curve sharply, since terms change by multiplication, not addition.","visual":"📈"},{"title":"A Bouncing Ball","body":"A ball dropped from 24 feet bounces to 3/4 of its previous height each time: 18, 13.5, 10.125, … feet. This is a GP with a = 18 and r = 0.75 (or 3/4).","visual":"🏀"}],"questions":[{"kind":"numeric","prompt":"The GP of green squares is 3, 6, 12, 24, 48, …. Find its 8th term.","answer":384,"explain":"tn = 3×2^(n-1); t8 = 3×128 = 384."},{"kind":"mcq","prompt":"What is the common ratio of the GP 5, 15/4, 45/16, 135/64, …?","options":["3/4","4/3","15/4","3/16"],"answer":0,"explain":"Each term is 3/4 of the one before it, e.g. (15/4)÷5 = 3/4."},{"kind":"numeric","prompt":"In the Sierpiński triangle, the number of black triangles at stage n is 3^n. How many black triangles are at Stage 5?","answer":243,"explain":"3^5 = 243."},{"kind":"numeric","prompt":"A GP has common ratio 2 and its 8th term is 192. Find its 12th term.","answer":3072,"explain":"a = 192/2^7 = 1.5; t12 = 1.5×2^11 = 3072."},{"kind":"numeric","prompt":"Which term of the GP 2, 6, 18, … equals 4374?","answer":8,"explain":"tn = 2×3^(n-1) = 4374 gives 3^(n-1) = 2187 = 3^7, so n = 8."}]},{"id":"sq-boss","title":"Guardian of the Final Chapter","icon":"👑","kind":"boss","story":"At the heart of the ruins stands the Guardian of Ganita Manjari, keeper of every sequence, every difference, every ratio in the book. To pass beyond the final chapter, you must answer for everything you have learned — sequences, explicit and recursive rules, arithmetic and geometric progressions alike.","teach":[{"title":"The Whole Chapter, One Vault","body":"Sequences are ordered lists of terms, described either explicitly (tn as a formula in n) or recursively (tn built from earlier terms). Arithmetic progressions add a constant d each time; geometric progressions multiply by a constant ratio r each time.","visual":"🗝️"},{"title":"Key Formulas to Remember","body":"AP: tn = a + (n−1)d. GP: tn = ar^(n−1). Sum of the first n natural numbers: Sn = n(n+1)/2, which is also the formula for the nth triangular number.","visual":"📋"}],"questions":[{"kind":"numeric","prompt":"The AP 11, 8, 5, 2, … has a = 11 and d = -3. Find its 20th term.","answer":-46,"explain":"t20 = 11 + 19(-3) = 11 - 57 = -46."},{"kind":"numeric","prompt":"Find the sum of the first 50 natural numbers.","answer":1275,"explain":"S50 = 50(51)/2 = 1275."},{"kind":"mcq","prompt":"What is the recursive rule for the GP 3, 30, 300, 3000, … (explicit rule tn = 3×10^(n-1))?","options":["t1 = 3, tn = 10×tn-1","t1 = 3, tn = tn-1 + 10","t1 = 3, tn = 3×tn-1","t1 = 10, tn = 3×tn-1"],"answer":0,"explain":"Each term is 10 times the one before it, so tn = 10×tn-1 with t1 = 3."},{"kind":"numeric","prompt":"Bacteria double every hour, starting with 30 bacteria. How many are present at the end of the 4th hour?","answer":480,"explain":"30×2^4 = 480."},{"kind":"numeric","prompt":"The Virahānka–Fibonacci sequence starts 1, 2, 3, 5, 8, 13, 21, 34, 55, …. What is its 10th term?","answer":89,"explain":"Each term is the sum of the two before it: 34+55 = 89."},{"kind":"mcq","prompt":"Which of these sequences is a geometric progression?","options":["1, -1, 1, -1, 1, …","1, 2, 3, 4, 5, …","2, 5, 8, 11, …","1, 3, 6, 10, …"],"answer":0,"explain":"1, -1, 1, -1, 1, … has a constant common ratio of -1; the others have a constant common difference or no fixed ratio at all."},{"kind":"numeric","prompt":"Find the sum 1 + 2 + 3 + … + 100.","answer":5050,"explain":"S100 = 100(101)/2 = 5050."},{"kind":"numeric","prompt":"Which term of the GP 2, 8, 32, … equals 131072?","answer":9,"explain":"tn = 2×4^(n-1) = 131072 gives 4^(n-1) = 65536 = 4^8, so n = 9."}],"boss":{"name":"The Guardian of Ganita Manjari","taunt":"Every sequence you've mastered stands between us — predict correctly, or your pattern ends here."}}]}];